css:
@property --mmd-chapters-a {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

/* Re-theme with --mmd-chapters-bg, -fg and -accent. */
.mmd-chapters {
  --mmd-chapters-bg: oklch(0.185 0.012 62);
  --mmd-chapters-fg: oklch(0.965 0.012 85);
  --mmd-chapters-accent: oklch(0.78 0.155 62);
  --mmd-chapters-r: 16px;

  --mmd-chapters-dim: color-mix(in oklch, var(--mmd-chapters-fg) 58%, var(--mmd-chapters-bg));
  --mmd-chapters-line: color-mix(in oklch, var(--mmd-chapters-fg) 11%, transparent);
  --mmd-chapters-raise: color-mix(in oklch, var(--mmd-chapters-fg) 8%, var(--mmd-chapters-bg));
  --mmd-chapters-pop: color-mix(in oklch, var(--mmd-chapters-fg) 5%, oklch(0.15 0.01 60));
  --mmd-chapters-ink: color-mix(in oklch, var(--mmd-chapters-accent) 14%, oklch(0.17 0.02 60));
  --mmd-chapters-rail: color-mix(in oklch, var(--mmd-chapters-fg) 17%, transparent);
  --mmd-chapters-buf: color-mix(in oklch, var(--mmd-chapters-fg) 36%, transparent);
  --mmd-chapters-gap: 3px;
  --mmd-chapters-ease: cubic-bezier(.22, 1, .36, 1);
  --mmd-chapters-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  container-type: inline-size;
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-areas: "screen" "scrub" "ctrls";
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  border: 1px solid var(--mmd-chapters-line);
  border-radius: var(--mmd-chapters-r);
  overflow: hidden;
  overflow: clip;
  background: var(--mmd-chapters-bg);
  color: var(--mmd-chapters-fg);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mmd-chapters { --mmd-chapters-spring: cubic-bezier(.3, 1.4, .5, 1); }
}
:where(.mmd-chapters) *, :where(.mmd-chapters) *::before, :where(.mmd-chapters) *::after { box-sizing: border-box; }
:where(.mmd-chapters) :is(p, h3, ol) { margin: 0; padding: 0; }
:where(.mmd-chapters) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mmd-chapters) :focus-visible { outline: 2px solid var(--mmd-chapters-accent); outline-offset: 2px; }
.mmd-chapters svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

/* ---------- the screen ---------- */
.mmd-chapters__screen {
  grid-area: screen;
  position: relative;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background: oklch(0.14 0.02 260);
  cursor: pointer;
}
.mmd-chapters__cv { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.mmd-chapters__shade {
  position: absolute; inset: 0; pointer-events: none;
  background:
    linear-gradient(to bottom, oklch(0.12 0.01 60 / .74), transparent 46%),
    linear-gradient(to top, oklch(0.12 0.01 60 / .45), transparent 34%);
  transition: opacity .6s var(--mmd-chapters-ease);
}
.mmd-chapters__title {
  position: absolute; inset: 12px 14px auto; pointer-events: none;
  transition: opacity .35s linear, translate .5s var(--mmd-chapters-ease);
  & p { font-size: 10px; font-weight: 650; letter-spacing: .12em; text-transform: uppercase; color: var(--mmd-chapters-accent); }
  & h3 {
    margin-top: 3px; max-width: 20ch;
    font: 680 clamp(15px, 5.2cqi, 21px)/1.12 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    letter-spacing: -.015em; text-wrap: balance;
    text-shadow: 0 1px 14px oklch(0 0 0 / .45);
  }
}
.mmd-chapters[data-state="playing"] {
  & .mmd-chapters__shade { opacity: .2; }
  & .mmd-chapters__title { opacity: 0; translate: 0 -6px; }
}
.mmd-chapters:has(.mmd-chapters__sheet[data-open]) .mmd-chapters__title { opacity: 0; }

.mmd-chapters__cc {
  position: absolute; left: 50%; bottom: 9px; translate: -50% 0;
  width: max-content; max-width: calc(100% - 28px);
  text-align: center; pointer-events: none;
  font-size: clamp(11px, 3.6cqi, 14px); line-height: 1.42; font-weight: 500; text-wrap: balance;
  & span {
    padding: 2px 7px; border-radius: 4px;
    background: oklch(0.1 0 0 / .74); color: oklch(0.98 0 0);
    -webkit-box-decoration-break: clone; box-decoration-break: clone;
  }
  & span:empty { display: none; }
}
.mmd-chapters[data-cc="off"] .mmd-chapters__cc { display: none; }

.mmd-chapters__spin {
  position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: 10px;
  pointer-events: none; opacity: 0; transition: opacity .2s linear;
  font-size: 11.5px; font-weight: 550; letter-spacing: .02em; color: oklch(0.96 0.01 85 / .85);
  & i {
    width: 34px; height: 34px; border-radius: 50%;
    background: conic-gradient(from var(--mmd-chapters-a), transparent 0 30%, var(--mmd-chapters-accent));
    -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 3.5px), #000 calc(100% - 3px));
    mask: radial-gradient(farthest-side, transparent calc(100% - 3.5px), #000 calc(100% - 3px));
    animation: mmd-chapters-turn .9s linear infinite paused;
  }
}
.mmd-chapters[data-state="buffering"] .mmd-chapters__spin span { display: none; }
.mmd-chapters:is([data-state="loading"], [data-state="buffering"]) .mmd-chapters__spin {
  opacity: 1; transition-delay: .1s;
  & i { animation-play-state: running; }
}
@keyframes mmd-chapters-turn { to { --mmd-chapters-a: 360deg; } }

.mmd-chapters__bezel {
  position: absolute; left: 50%; top: 50%; width: 54px; height: 54px; margin: -27px 0 0 -27px;
  display: grid; place-items: center; border-radius: 50%;
  background: oklch(0.12 0 0 / .55); color: oklch(0.98 0 0);
  opacity: 0; pointer-events: none;
  & svg { width: 24px; height: 24px; stroke-width: 2.2; }
  & path { display: none; }
  & path:is([data-g="play"], [data-g="pause"]) { fill: currentColor; stroke: none; }
}
.mmd-chapters__bezel[data-g="play"] path[data-g="play"],
.mmd-chapters__bezel[data-g="pause"] path[data-g="pause"],
.mmd-chapters__bezel[data-g="back"] path[data-g="back"],
.mmd-chapters__bezel[data-g="fwd"] path[data-g="fwd"] { display: block; }

.mmd-chapters__big {
  position: absolute; left: 50%; top: 58%; translate: -50% -50%;
  display: none; align-items: center; gap: 10px;
  padding: 6px 16px 6px 6px; border-radius: 999px;
  background: oklch(0.13 0.01 60 / .66); color: var(--mmd-chapters-fg);
  box-shadow: inset 0 0 0 1px oklch(1 0 0 / .14), 0 12px 30px -12px oklch(0 0 0 / .7);
  font-size: 13px; font-weight: 620; white-space: nowrap;
  transition: opacity .3s linear, scale .5s var(--mmd-chapters-spring), background-color .2s, display .3s allow-discrete;
  & small { margin-left: 4px; font: 500 12px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mmd-chapters-dim); }
  &:hover { background: oklch(0.13 0.01 60 / .82); scale: 1.04; }
  &:active { scale: .97; }
}
.mmd-chapters__disc {
  width: 38px; height: 38px; border-radius: 50%; display: grid; place-items: center;
  background: var(--mmd-chapters-accent); color: var(--mmd-chapters-ink);
  & svg { width: 18px; height: 18px; }
  & .mmd-chapters__gplay { fill: currentColor; stroke: none; }
  & .mmd-chapters__greplay { display: none; stroke-width: 2.2; }
}
.mmd-chapters:is([data-state="ready"], [data-state="ended"]) .mmd-chapters__big {
  display: inline-flex;
  @starting-style { opacity: 0; scale: .9; }
}
.mmd-chapters[data-state="ended"] {
  & .mmd-chapters__gplay { display: none; }
  & .mmd-chapters__greplay { display: block; }
  & .mmd-chapters__shade { opacity: 1; background: oklch(0.12 0.01 60 / .55); }
}

/* ---------- chapter sheet ---------- */
.mmd-chapters__sheet {
  position: absolute; inset: 0 0 0 auto; z-index: 4;
  width: min(100%, 264px);
  display: none; flex-direction: column;
  background: color-mix(in oklch, var(--mmd-chapters-bg) 94%, transparent);
  box-shadow: -1px 0 0 var(--mmd-chapters-line), -24px 0 40px -20px oklch(0 0 0 / .7);
  cursor: default;
  translate: 100% 0; opacity: 0;
  transition: translate .38s var(--mmd-chapters-ease), opacity .2s linear, display .38s allow-discrete;
  & header {
    display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 8px;
    padding: 8px 6px 6px 12px;
  }
  & header b { font-size: 12px; font-weight: 680; letter-spacing: .06em; text-transform: uppercase; }
  & header span { font: 500 11px/1 ui-monospace, Menlo, monospace; color: var(--mmd-chapters-dim); }
  & header button { width: 28px; height: 28px; display: grid; place-items: center; border-radius: 8px; color: var(--mmd-chapters-dim); }
  & header button:hover { background: var(--mmd-chapters-raise); color: var(--mmd-chapters-fg); }
}
.mmd-chapters__sheet[data-open] {
  display: flex; translate: 0 0; opacity: 1;
  @starting-style { translate: 100% 0; opacity: 0; }
}
.mmd-chapters__chs {
  list-style: none; overflow-y: auto; overscroll-behavior: contain; padding: 0 6px 8px;
  scrollbar-width: thin; scrollbar-color: var(--mmd-chapters-rail) transparent;
  & li { opacity: 1; }
  & button {
    position: relative; width: 100%;
    display: grid; grid-template-columns: 64px minmax(0, 1fr); grid-template-areas: "thumb name" "thumb meta";
    column-gap: 10px; align-items: center; padding: 5px; border-radius: 10px; text-align: left;
    transition: background-color .15s;
  }
  & button:hover { background: var(--mmd-chapters-raise); }
  & canvas { grid-area: thumb; width: 64px; height: 36px; border-radius: 6px; display: block; background: oklch(0.25 0.02 250); box-shadow: inset 0 0 0 1px var(--mmd-chapters-line); }
  & b { grid-area: name; align-self: end; font-size: 12.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { grid-area: meta; align-self: start; font: 500 11px/1.4 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mmd-chapters-dim); }
  & button[aria-current="true"] { background: color-mix(in oklch, var(--mmd-chapters-accent) 14%, transparent); }
  & button[aria-current="true"] b { color: var(--mmd-chapters-accent); }
  & button[aria-current="true"] canvas { box-shadow: 0 0 0 2px var(--mmd-chapters-accent); }
}
.mmd-chapters__sheet[data-open] li { animation: mmd-chapters-in .45s var(--mmd-chapters-ease) both; animation-delay: calc(var(--i) * 40ms + 80ms); }
@keyframes mmd-chapters-in { from { opacity: 0; transform: translateX(16px); } }

/* ---------- scrubber ---------- */
.mmd-chapters__scrub {
  grid-area: scrub; position: relative; z-index: 2;
  padding: 9px 14px 3px; cursor: pointer; touch-action: none; outline: none;
  &[aria-disabled="true"] { cursor: default; pointer-events: none; }
  &:focus-visible .mmd-chapters__segs { outline: 2px solid var(--mmd-chapters-accent); outline-offset: 4px; border-radius: 3px; }
}
.mmd-chapters__segs {
  position: relative; container-type: inline-size;
  display: flex; gap: var(--mmd-chapters-gap); height: 16px;
}
.mmd-chapters__seg { flex: var(--d) 1 0; min-width: 0; height: 100%; display: grid; align-items: center; }
.mmd-chapters__rail {
  position: relative; height: 4px; border-radius: 2px; overflow: hidden;
  background: var(--mmd-chapters-rail);
  transition: scale .3s var(--mmd-chapters-spring);
  &::before, &::after { content: ""; position: absolute; inset: 0; transform-origin: 0 50%; }
  &::before { background: var(--mmd-chapters-buf); transform: scaleX(var(--b, 0)); }
  &::after { background: var(--mmd-chapters-accent); transform: scaleX(var(--f, 0)); }
}
.mmd-chapters__scrub:is(:hover, [data-drag]) .mmd-chapters__rail { scale: 1 1.5; }
.mmd-chapters__seg:hover .mmd-chapters__rail { scale: 1 2.25; }
.mmd-chapters__knob {
  position: absolute; left: 0; top: 50%; z-index: 1;
  width: 13px; height: 13px; margin: -6.5px 0 0 -6.5px; border-radius: 50%;
  background: var(--mmd-chapters-accent);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--mmd-chapters-accent) 26%, transparent), 0 2px 6px oklch(0 0 0 / .5);
  translate: calc((100cqi - var(--gaps, 4) * var(--mmd-chapters-gap)) * var(--p, 0) + var(--ci, 0) * var(--mmd-chapters-gap)) 0;
  scale: .72; pointer-events: none;
  transition: scale .3s var(--mmd-chapters-spring);
}
.mmd-chapters__scrub:is(:hover, :focus-visible, [data-drag]) .mmd-chapters__knob { scale: 1; }
.mmd-chapters__peek {
  position: absolute; left: 0; bottom: calc(100% + 10px); z-index: 3;
  width: 120px; display: grid; justify-items: center; gap: 5px; pointer-events: none;
  translate: clamp(0px, var(--x, 0px) - 50%, 100cqi - 100%) 0;
  opacity: 0; scale: .9; transform-origin: 50% 100%;
  transition: opacity .14s linear, scale .3s var(--mmd-chapters-spring);
  & canvas {
    width: 120px; height: 67.5px; display: block; border-radius: 8px; background: oklch(0.2 0.02 250);
    box-shadow: 0 0 0 1.5px oklch(0.98 0 0 / .9), 0 12px 26px -8px oklch(0 0 0 / .75);
  }
  & p {
    display: grid; justify-items: center; padding: 3px 8px 4px; border-radius: 7px;
    background: oklch(0.12 0.01 60 / .86); max-width: 100%;
  }
  & b { font: 600 11.5px/1.2 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
  & span { font-size: 10.5px; font-weight: 550; color: var(--mmd-chapters-accent); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 110px; }
}
.mmd-chapters__scrub[data-peek] .mmd-chapters__peek { opacity: 1; scale: 1; }
.mmd-chapters:has(.mmd-chapters__scrub[data-peek]) .mmd-chapters__cc { opacity: 0; }

/* ---------- controls ---------- */
.mmd-chapters__ctrls {
  grid-area: ctrls;
  display: grid; grid-template-columns: auto auto auto auto minmax(0, 1fr) auto auto auto auto;
  align-items: center; gap: 2px; padding: 2px 8px 6px;
}
.mmd-chapters__btn {
  height: 32px; min-width: 32px; display: inline-grid; place-items: center; border-radius: 9px;
  color: var(--mmd-chapters-dim);
  transition: background-color .15s, color .15s;
  & svg { transition: scale .25s var(--mmd-chapters-spring); }
  &:hover { background: var(--mmd-chapters-raise); color: var(--mmd-chapters-fg); }
  &:active svg { scale: .86; }
  &[aria-pressed="true"], &[aria-expanded="true"] { color: var(--mmd-chapters-fg); }
  &:disabled { opacity: .38; cursor: default; background: none; }
}
.mmd-chapters__btn[data-act="play"] {
  color: var(--mmd-chapters-fg);
  & .mmd-chapters__gplay { fill: currentColor; stroke-width: 1.4; }
  & .mmd-chapters__gpause { display: none; stroke-width: 2.6; }
}
.mmd-chapters[data-playing] .mmd-chapters__btn[data-act="play"] {
  & .mmd-chapters__gplay { display: none; }
  & .mmd-chapters__gpause { display: block; }
}
.mmd-chapters__btn[data-act="cc"][aria-pressed="true"] { color: var(--mmd-chapters-accent); }
.mmd-chapters__w1, .mmd-chapters__w2, .mmd-chapters__wx { display: none; }
.mmd-chapters[data-vol="low"] .mmd-chapters__w1,
.mmd-chapters[data-vol="high"] :is(.mmd-chapters__w1, .mmd-chapters__w2),
.mmd-chapters[data-vol="off"] .mmd-chapters__wx { display: block; }
.mmd-chapters__time {
  padding: 0 6px 0 5px; white-space: nowrap;
  font: 500 12px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
  & span { color: var(--mmd-chapters-dim); }
}
.mmd-chapters__chap {
  justify-self: start; max-width: 100%; display: inline-flex; align-items: center; gap: 6px; padding: 0 9px 0 7px;
  color: var(--mmd-chapters-fg);
  & svg { width: 16px; height: 16px; color: var(--mmd-chapters-dim); }
  & span { min-width: 0; font-size: 12px; font-weight: 580; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.mmd-chapters__vol { width: 62px; margin: 0 4px 0 0; accent-color: var(--mmd-chapters-accent); cursor: pointer; }
.mmd-chapters__rate { min-width: 38px; font: 600 12px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mmd-chapters-fg); }

.mmd-chapters__menu {
  position: absolute; right: 8px; bottom: 44px; z-index: 6;
  display: none; min-width: 136px; padding: 5px;
  border-radius: 12px; background: var(--mmd-chapters-pop);
  box-shadow: 0 0 0 1px var(--mmd-chapters-line), 0 18px 40px -14px oklch(0 0 0 / .85);
  transform-origin: 100% 100%; opacity: 0; scale: .94;
  transition: opacity .15s linear, scale .3s var(--mmd-chapters-spring), display .3s allow-discrete;
  & p { padding: 4px 9px 5px; font-size: 10px; font-weight: 680; letter-spacing: .1em; text-transform: uppercase; color: var(--mmd-chapters-dim); }
  & button {
    width: 100%; display: grid; grid-template-columns: 16px auto 1fr; align-items: center; gap: 8px;
    padding: 6px 10px 6px 7px; border-radius: 8px; text-align: left;
    font: 500 12.5px/1.2 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
  }
  & button:is(:hover, :focus-visible) { background: var(--mmd-chapters-raise); outline: none; }
  & svg { width: 15px; height: 15px; stroke-width: 2.2; color: var(--mmd-chapters-accent); opacity: 0; }
  & small { justify-self: end; font: 500 10.5px/1 system-ui, sans-serif; color: var(--mmd-chapters-dim); }
  & [aria-checked="true"] { color: var(--mmd-chapters-accent); }
  & [aria-checked="true"] svg { opacity: 1; }
}
.mmd-chapters__menu[data-open] {
  display: block; opacity: 1; scale: 1;
  @starting-style { opacity: 0; scale: .94; }
  & button { animation: mmd-chapters-in .32s var(--mmd-chapters-ease) both; animation-delay: calc(var(--i) * 22ms); }
}
.mmd-chapters__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (width < 470px) {
  .mmd-chapters__vol { display: none; }
}
@container (width < 400px) {
  .mmd-chapters__btn:is([data-act="back"], [data-act="fwd"]) { display: none; }
  .mmd-chapters__time { padding-left: 2px; }
}
@container (width < 320px) {
  .mmd-chapters__chap span { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .mmd-chapters, .mmd-chapters *, .mmd-chapters *::before, .mmd-chapters *::after {
    transition-duration: .01ms !important;
    animation-duration: .01ms !important;
    animation-delay: 0s !important;
  }
  .mmd-chapters__spin i {
    animation: none;
    background: conic-gradient(var(--mmd-chapters-accent) 0 28%, var(--mmd-chapters-rail) 0);
  }
  .mmd-chapters__rail, .mmd-chapters__knob { transition: none; }
  .mmd-chapters__seg:hover .mmd-chapters__rail, .mmd-chapters__scrub:is(:hover, [data-drag]) .mmd-chapters__rail { scale: 1 1.5; }
}

