const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');

/* ---------- the film: one source of truth for chapters, captions and look ---------- */
const DUR = 252;
const CH = [[0, 'Cold open'], [38, 'The keeper’s log'], [84, 'Storm season'], [151, 'Automation'], [220, 'Last light']]
  .map(([t, name], i, a) => ({ t, name, end: i < a.length - 1 ? a[i + 1][0] : DUR }));
const CUES = [
  [2, 7.5, 'Skerry Light stands eleven miles out, on a rock you can cross in forty steps.'],
  [9, 14, 'For ninety-one years somebody lived here. Always somebody.'],
  [17, 23, 'Agnes Mallory was the last of them.'],
  [40, 46.5, 'Log, 4 March 1987. Wind north-east, force six. Lamp lit 18:02.'],
  [49, 55, 'I wrote everything down. The log was the only one listening.'],
  [60, 66, 'Twelve thousand pages. Weather, ships, the odd seal.'],
  [86, 91, '[wind rising]'],
  [95, 101, 'The winter of ’89, the sea came over the gallery rail.'],
  [110, 117, 'You don’t sleep. You keep the light turning and you count.'],
  [125, 131, 'Three ships that night. All three made harbour.'],
  [153, 159, 'In 1994 the board sent a letter. Two paragraphs.'],
  [165, 171, 'A sensor, a battery bank, a lamp that would never get tired.'],
  [180, 186, 'I trained the engineers myself. They were kind about it.'],
  [222, 228, 'On the last night I lit it by hand, once, for the record.'],
  [236, 242, 'Then I rowed home and watched it from the kitchen window.'],
  [246, 251.5, '[lamp turning]']
];
/* time, sky top, horizon, sea, storm 0..1, night 0..1 */
const SKY = [
  [0, [26, 34, 70], [238, 154, 112], [40, 52, 82], 0, .55],
  [34, [86, 124, 178], [240, 200, 164], [52, 82, 112], 0, .12],
