  '<li style="--i:' + i + '"><button type="button" data-ch="' + i + '"><canvas width="128" height="72" aria-hidden="true"></canvas>' +
  '<b>' + c.name + '</b><small>' + fmt(c.t) + ' · ' + span(c.end - c.t) + '</small></button></li>').join('');
