menu.addEventListener('keydown', (e) => {
  if (e.key === 'Tab') { closeMenu(false); return; }
  roving($$('[role="menuitemradio"]', menu), e);
});
list.addEventListener('keydown', (e) => { roving(chBtns, e); });
root.addEventListener('keydown', (e) => {
  if (e.defaultPrevented || e.altKey || e.ctrlKey || e.metaKey) return;
  if (e.key === 'Escape') {
    if (isOpen(menu)) { e.preventDefault(); closeMenu(true); }
    else if (isOpen(sheet)) { e.preventDefault(); closeSheet(true); }
    return;
  }
  if (state === 'loading' || e.target === volEl || e.target.closest('.mmd-chapters__menu, .mmd-chapters__sheet')) return;
  const k = e.key.toLowerCase();
  if (k === 'k' || (k === ' ' && !e.target.closest('button'))) toggle();
  else if (k === 'j') ACT.back();
  else if (k === 'l') ACT.fwd();
  else if (k === 'm') ACT.mute();
  else if (k === 'c') ACT.cc();
  else return;
  e.preventDefault();
});
volEl.addEventListener('input', () => { vol = +volEl.value; muted = vol === 0; syncVol(); });

/* ---------- lifecycle ---------- */
const dpr = () => Math.min(2, window.devicePixelRatio || 1);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) return teardown();
  const r = dpr(), w = Math.round(cv.clientWidth * r), h = Math.round(cv.clientHeight * r);
  if (w && (cv.width !== w || cv.height !== h)) { cv.width = w; cv.height = h; }
  gap = parseFloat(getComputedStyle(segsEl).columnGap) || 3;
  sr = null;
  draw();
});
ro.observe(screen);
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) return teardown();
  visible = es[es.length - 1].isIntersecting;
  kick();
});
io.observe(root);
const onVis = () => { if (!root.isConnected) return teardown(); kick(); };
document.addEventListener('visibilitychange', onVis);
function teardown() {
  cancelAnimationFrame(raf); raf = 0; clearTimeout(bufT);
  io.disconnect(); ro.disconnect();
  document.removeEventListener('visibilitychange', onVis);
}

setState('loading');
syncVol();
draw();
later(RM.matches ? 300 : 950, () => {
  buffered = 36;
  $$('[disabled]').forEach((el) => { el.disabled = false; });
  scrub.removeAttribute('aria-disabled');
  setState('ready');
  $$('canvas', list).forEach((c, i) => paint(c.getContext('2d'), c.width, c.height, Math.min(CH[i].t + 9, CH[i].end - 1)));
  draw();
});

