@property --mmd-clip-pct {
  syntax: "<integer>";
  inherits: true;
  initial-value: 0;
}
@property --mmd-clip-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

/* Re-theme with --mmd-clip-paper, -ink and -accent (and -bad for the over-limit state). */
.mmd-clip {
  --mmd-clip-paper: oklch(0.972 0.012 88);
  --mmd-clip-ink: oklch(0.26 0.022 60);
  --mmd-clip-accent: oklch(0.56 0.1 192);
  --mmd-clip-bad: oklch(0.6 0.19 35);

  --mmd-clip-dim: color-mix(in oklch, var(--mmd-clip-ink) 58%, var(--mmd-clip-paper));
  --mmd-clip-line: color-mix(in oklch, var(--mmd-clip-ink) 13%, transparent);
  --mmd-clip-well: color-mix(in oklch, var(--mmd-clip-ink) 5%, var(--mmd-clip-paper));
  --mmd-clip-wave: color-mix(in oklch, var(--mmd-clip-ink) 30%, var(--mmd-clip-paper));
  --mmd-clip-played: color-mix(in oklch, var(--mmd-clip-accent) 55%, var(--mmd-clip-ink));
  --mmd-clip-tint: color-mix(in oklch, var(--mmd-clip-accent) 15%, transparent);
  --mmd-clip-mark: color-mix(in oklch, var(--mmd-clip-accent) 17%, var(--mmd-clip-paper));
  --mmd-clip-tone: var(--mmd-clip-accent);
  --mmd-clip-ease: cubic-bezier(.22, 1, .36, 1);
  --mmd-clip-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "wave" "ruler" "read" "text" "foot";
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 14px 14px 12px;
  border-radius: 18px;
  background: var(--mmd-clip-paper);
  color: var(--mmd-clip-ink);
  box-shadow: 0 0 0 1px var(--mmd-clip-line), 0 18px 40px -26px oklch(0.2 0.03 60 / .55);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
.mmd-clip:has(.mmd-clip__len[data-over]) { --mmd-clip-tone: var(--mmd-clip-bad); --mmd-clip-tint: color-mix(in oklch, var(--mmd-clip-bad) 13%, transparent); --mmd-clip-mark: color-mix(in oklch, var(--mmd-clip-bad) 15%, var(--mmd-clip-paper)); }
@supports not (transition-timing-function: linear(0, 1)) {
  .mmd-clip { --mmd-clip-spring: cubic-bezier(.3, 1.4, .5, 1); }
}
:where(.mmd-clip) *, :where(.mmd-clip) *::before, :where(.mmd-clip) *::after { box-sizing: border-box; }
:where(.mmd-clip) :is(p, h3) { margin: 0; }
:where(.mmd-clip) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mmd-clip) :focus-visible { outline: 2px solid var(--mmd-clip-accent); outline-offset: 2px; }
.mmd-clip svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

/* ---------- head ---------- */
.mmd-clip__head { grid-area: head; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 11px; margin-bottom: 12px; }
.mmd-clip__art {
  width: 44px; height: 44px; border-radius: 10px;
  & rect { fill: var(--mmd-clip-ink); stroke: none; }
  & circle { fill: var(--mmd-clip-accent); stroke: none; }
  & path { stroke: var(--mmd-clip-paper); stroke-width: 2; }
}
.mmd-clip__who {
  min-width: 0;
  & p { font-size: 10px; font-weight: 700; letter-spacing: .11em; text-transform: uppercase; color: var(--mmd-clip-accent); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & h3 { font-size: clamp(15px, 4.6cqi, 17px); font-weight: 720; letter-spacing: -.015em; line-height: 1.15; text-wrap: balance; }
  & span { display: block; font-size: 11.5px; color: var(--mmd-clip-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.mmd-clip__src {
  display: grid; justify-items: end; line-height: 1.15;
  & b { font: 600 13px/1.2 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
  & small { font-size: 10px; letter-spacing: .06em; text-transform: uppercase; color: var(--mmd-clip-dim); }
}

/* ---------- waveform ---------- */
.mmd-clip__wave {
  grid-area: wave; position: relative; container-type: inline-size;
  height: clamp(72px, 24cqi, 92px); border-radius: 10px;
  background:
    linear-gradient(var(--mmd-clip-line), var(--mmd-clip-line)) 0 50% / 100% 1px no-repeat,
    var(--mmd-clip-well);
  touch-action: none; cursor: text;
  --a: 0; --b: 0; --p: 0;
}
.mmd-clip__cvs {
  position: absolute; inset: 0;
  clip-path: inset(0 0 0 0);
  transition: clip-path 1s cubic-bezier(.5, 0, .2, 1);
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
  & [data-layer="sel"] { clip-path: inset(0 calc((1 - var(--b)) * 100%) 0 calc(var(--a) * 100%)); }
  & [data-layer="played"] { clip-path: inset(0 calc((1 - min(var(--p), var(--b))) * 100%) 0 calc(var(--a) * 100%)); }
}
.mmd-clip:has(.mmd-clip__len[data-over]) .mmd-clip__cvs [data-layer="played"] { opacity: 0; }
.mmd-clip__region {
  position: absolute; inset: 0;
  background: var(--mmd-clip-tint);
  border-block: 2px solid var(--mmd-clip-tone);
  clip-path: inset(0 calc((1 - var(--b)) * 100%) 0 calc(var(--a) * 100%));
  cursor: grab;
  transition: background-color .25s, border-color .25s;
}
.mmd-clip__wave[data-drag="move"] .mmd-clip__region { cursor: grabbing; }
.mmd-clip__ph {
  position: absolute; left: -1px; top: -3px; bottom: -3px; width: 2px; border-radius: 1px;
  background: var(--mmd-clip-ink); pointer-events: none;
  translate: calc(var(--p) * 100cqi) 0;
  &::before { content: ""; position: absolute; left: -3px; top: -2px; width: 8px; height: 8px; border-radius: 50%; background: var(--mmd-clip-ink); }
}
.mmd-clip__h {
  position: absolute; top: -5px; bottom: -5px; left: -7px; width: 14px; z-index: 2;
  display: grid; place-items: center; border-radius: 5px;
  background: var(--mmd-clip-tone); cursor: ew-resize; touch-action: none;
  box-shadow: 0 2px 8px -2px oklch(0.2 0.03 60 / .45);
  transition: background-color .25s, scale .3s var(--mmd-clip-spring);
  &::before { content: ""; width: 2px; height: 34%; border-radius: 1px; background: color-mix(in oklch, var(--mmd-clip-paper) 85%, transparent); box-shadow: -3px 0 0 color-mix(in oklch, var(--mmd-clip-paper) 45%, transparent); }
  &:hover, .mmd-clip__wave[data-drag] &.is-drag { scale: 1.12 1.04; }
  &:focus-visible { outline-offset: 3px; }
}
.mmd-clip__h[data-h="a"] { translate: calc(var(--a) * 100cqi) 0; }
.mmd-clip__h[data-h="b"] { translate: calc(var(--b) * 100cqi) 0; }
.mmd-clip__scan {
  position: absolute; inset: 0; display: grid; place-items: center; pointer-events: none;
  font-size: 11.5px; font-weight: 600; letter-spacing: .02em; color: var(--mmd-clip-dim);
  opacity: 0; transition: opacity .3s;
}
.mmd-clip[data-state="loading"] {
  & .mmd-clip__cvs { clip-path: inset(0 100% 0 0); transition: none; }
  & .mmd-clip__scan { opacity: 1; }
  & .mmd-clip__scan span { animation: mmd-clip-breathe 1.2s ease-in-out infinite alternate; }
  & :is(.mmd-clip__region, .mmd-clip__h, .mmd-clip__ph) { opacity: 0; }
}
.mmd-clip :is(.mmd-clip__region, .mmd-clip__h, .mmd-clip__ph) { transition: opacity .4s .7s, background-color .25s, border-color .25s, scale .3s var(--mmd-clip-spring); }
@keyframes mmd-clip-breathe { from { opacity: .45; } to { opacity: 1; } }

.mmd-clip__ruler {
  grid-area: ruler; position: relative; height: 18px; margin-top: 4px;
  font: 500 10px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mmd-clip-dim);
  & span { position: absolute; top: 5px; translate: -50% 0; }
  & span::before { content: ""; position: absolute; left: 50%; top: -5px; width: 1px; height: 3px; background: currentColor; opacity: .6; }
  & span:first-child { translate: 0 0; }
  & span:first-child::before { left: 0; }
}

/* ---------- readout ---------- */
.mmd-clip__read {
  grid-area: read; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px;
  padding: 6px 0 9px; border-bottom: 1px solid var(--mmd-clip-line);
  & p { display: flex; align-items: baseline; gap: 6px; }
  & small { font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--mmd-clip-dim); }
  & b { font: 600 13px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
}
.mmd-clip__len {
  margin-left: auto; align-items: center !important; gap: 5px !important;
  padding: 4px 9px; border-radius: 999px;
  background: var(--mmd-clip-tint); color: color-mix(in oklch, var(--mmd-clip-tone) 70%, var(--mmd-clip-ink));
  font: 650 12px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; white-space: nowrap;
  transition: background-color .25s, color .25s;
  & svg { width: 14px; height: 14px; display: none; }
  &[data-over] svg { display: block; animation: mmd-clip-nudge .45s var(--mmd-clip-ease); }
}
@keyframes mmd-clip-nudge { 30% { transform: translateX(-2px) rotate(-8deg); } 60% { transform: translateX(2px) rotate(6deg); } }

/* ---------- transcript ---------- */
.mmd-clip__text {
  grid-area: text; position: relative;
  max-height: 138px; overflow-y: auto; overscroll-behavior: contain;
  margin: 0 -6px; padding: 10px 6px 12px;
  font-size: 13px; line-height: 1.62; text-wrap: pretty;
  scrollbar-width: thin; scrollbar-color: var(--mmd-clip-line) transparent;
  -webkit-mask: linear-gradient(transparent, #000 var(--mmd-clip-fade), #000 calc(100% - 16px), transparent);
  mask: linear-gradient(transparent, #000 var(--mmd-clip-fade), #000 calc(100% - 16px), transparent);
  &:focus-visible { outline-offset: -2px; border-radius: 8px; }
  & p + p { margin-top: 8px; }
  & p > b { display: inline-flex; gap: 6px; align-items: baseline; margin-right: 6px; font-size: 10px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; }
  & p > b time { font: 500 10px/1 ui-monospace, Menlo, monospace; letter-spacing: 0; color: var(--mmd-clip-dim); }
  & p[data-who="T"] > b { color: var(--mmd-clip-accent); }
  & [data-w] { cursor: pointer; border-radius: 3px; transition: background-color .2s, color .2s, box-shadow .2s; }
  & [data-w]:hover { box-shadow: 0 1.5px 0 var(--mmd-clip-dim); }
  & [data-w][data-in] { background: var(--mmd-clip-mark); box-shadow: 0 0 0 2px var(--mmd-clip-mark); }
  & [data-w][data-now] { color: var(--mmd-clip-paper); background: var(--mmd-clip-played); box-shadow: 0 0 0 2px var(--mmd-clip-played); }
}
@supports (animation-timeline: scroll()) {
  .mmd-clip__text { animation: mmd-clip-fadein linear both; animation-timeline: scroll(self); animation-range: 0 28px; }
}
@supports not (animation-timeline: scroll()) {
  .mmd-clip__text { --mmd-clip-fade: 8px; }
}
@keyframes mmd-clip-fadein { to { --mmd-clip-fade: 18px; } }

/* ---------- footer + states ---------- */
.mmd-clip__foot {
  grid-area: foot; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding-top: 10px; border-top: 1px solid var(--mmd-clip-line);
}
.mmd-clip__play {
  width: 38px; height: 38px; border-radius: 50%; display: grid; place-items: center;
  background: var(--mmd-clip-ink); color: var(--mmd-clip-paper);
  transition: scale .3s var(--mmd-clip-spring), background-color .2s;
  & svg { width: 18px; height: 18px; }
  & .mmd-clip__gplay { fill: currentColor; stroke-width: 1.2; }
  & .mmd-clip__gpause { display: none; stroke-width: 2.6; }
  &:hover { background: color-mix(in oklch, var(--mmd-clip-ink) 85%, var(--mmd-clip-accent)); }
  &:active { scale: .92; }
}
.mmd-clip[data-state="playing"] .mmd-clip__play {
  & .mmd-clip__gplay { display: none; }
  & .mmd-clip__gpause { display: block; }
}
.mmd-clip__snap {
  display: inline-flex; align-items: center; gap: 7px; min-width: 0;
  font-size: 12px; font-weight: 550; color: var(--mmd-clip-dim); cursor: pointer; white-space: nowrap;
  & input { width: 15px; height: 15px; margin: 0; accent-color: var(--mmd-clip-accent); cursor: pointer; flex: none; }
  &:has(input:checked) { color: var(--mmd-clip-ink); }
}
.mmd-clip__go {
  position: relative; overflow: hidden; isolation: isolate;
  height: 36px; padding: 0 16px; border-radius: 999px;
  background: var(--mmd-clip-ink); color: var(--mmd-clip-paper);
  font-size: 12.5px; font-weight: 650; white-space: nowrap;
  font-variant-numeric: tabular-nums;
  transition: background-color .2s, opacity .2s, scale .3s var(--mmd-clip-spring);
  &::before {
    content: ""; position: absolute; inset: 0; z-index: -1; transform-origin: 0 50%;
    background: var(--mmd-clip-accent); transform: scaleX(calc(var(--mmd-clip-pct) / 100));
  }
  &::after { content: none; }
  &:not(:disabled):hover { background: color-mix(in oklch, var(--mmd-clip-ink) 85%, var(--mmd-clip-accent)); }
  &:not(:disabled):active { scale: .96; }
  &:disabled { cursor: not-allowed; opacity: .35; }
}
.mmd-clip[data-state="rendering"] .mmd-clip__go {
  counter-reset: mmd-clip-pct var(--mmd-clip-pct);
  animation: mmd-clip-render 1.9s cubic-bezier(.45, .05, .3, 1) forwards;
  & span { display: none; }
  &::after { content: "Rendering " counter(mmd-clip-pct) "%"; }
}
@keyframes mmd-clip-render { to { --mmd-clip-pct: 100; } }

.mmd-clip__done {
  grid-area: foot; display: none; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding-top: 10px; border-top: 1px solid var(--mmd-clip-line);
  & > svg { width: 30px; height: 30px; color: var(--mmd-clip-accent); stroke-width: 1.8; }
  & > svg path { stroke-dasharray: 14; stroke-dashoffset: 14; animation: mmd-clip-tick .5s .15s var(--mmd-clip-ease) forwards; }
  & p { display: grid; min-width: 0; line-height: 1.3; }
  & b { font-size: 13px; font-weight: 700; }
  & span { font: 500 11.5px/1.35 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mmd-clip-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & button { height: 32px; padding: 0 14px; border-radius: 999px; font-size: 12.5px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--mmd-clip-line); }
  & button:hover { background: var(--mmd-clip-well); }
}
@keyframes mmd-clip-tick { to { stroke-dashoffset: 0; } }
.mmd-clip[data-state="done"] {
  & .mmd-clip__foot { display: none; }
  & .mmd-clip__done { display: grid; animation: mmd-clip-rise .45s var(--mmd-clip-ease); }
  & :is(.mmd-clip__h, .mmd-clip__region) { pointer-events: none; }
}
@keyframes mmd-clip-rise { from { opacity: 0; transform: translateY(6px); } }
.mmd-clip:is([data-state="rendering"], [data-state="done"]) .mmd-clip__h { background: var(--mmd-clip-dim); }
.mmd-clip__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (width < 300px) {
  .mmd-clip__snap span span { display: none; }
}
@container (width < 340px) {
  .mmd-clip__who span { display: none; }
  .mmd-clip__read { gap: 10px; }
  .mmd-clip__snap { font-size: 11.5px; }
  .mmd-clip__go { padding: 0 13px; }
}

@media (prefers-reduced-motion: reduce) {
  .mmd-clip *, .mmd-clip *::before, .mmd-clip *::after { transition-duration: .01ms !important; transition-delay: 0s !important; }
  .mmd-clip[data-state="loading"] .mmd-clip__scan span { animation: none; opacity: .8; }
  .mmd-clip__len[data-over] svg, .mmd-clip[data-state="done"] .mmd-clip__done { animation: none; }
  .mmd-clip__done > svg path { animation: none; stroke-dashoffset: 0; }
  .mmd-clip[data-state="rendering"] .mmd-clip__go { animation-duration: .6s; animation-timing-function: steps(4, end); }
}

