const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const LIMIT = 60, MIN = 3;

/* ---------- the excerpt: transcript first, waveform derived from it ---------- */
const SCRIPT = [
  ['I', 'So the first summer, you didn’t sell any of it?'],
  ['T', 'Not a gram. We salted everything we owned. Tomatoes, fish, the neighbours’ fish. My brother kept a jar in his truck like it was holy water.'],
  ['I', 'And what changed?'],
  ['T', 'The weather, mostly. Salt is just patience with a sunny week attached. That second August we had nineteen dry days in a row, and the pans came up white, almost blue at the edges. A chef from the harbour walked past, licked his finger, and ordered forty kilos on the spot.'],
  ['I', 'Forty kilos, from one taste.'],
  ['T', 'He said it tasted like the tide going out. I still don’t know what that means, but I put it on the label.'],
  ['I', 'You rake every pan by hand. Why not machines?'],
  ['T', 'Because the crystals are fragile. A machine crushes the flake, and then you have table salt that cost me three months. With a wooden rake you skim the top, slowly, like taking cream off milk.'],
  ['I', 'How many pans now?'],
  ['T', 'Thirty-two. Same as my grandfather had, which wasn’t the plan. It turns out the marsh only gives you so much, and it doesn’t care what the spreadsheet says.'],
  ['I', 'And when a summer is wet?'],
  ['T', 'Then we sell less salt and more stories. People still drive out. They just go home with damp shoes.']
];
const NAMES = { I: 'Ines', T: 'Tomasz' };
const rnd = (n) => { const x = Math.sin(n * 91.7 + 17.3) * 43758.5453; return x - Math.floor(x); };
const WORDS = [], PARAS = [];
let clock = .5;
SCRIPT.forEach(([who, text], p) => {
  if (p) clock += .62;
  PARAS.push({ who, s: clock, from: WORDS.length });
  text.split(' ').forEach((w) => {
    const core = w.replace(/[^\p{L}’']/gu, '');
    const syl = Math.max(1, Math.round(core.length / 2.9));
    const d = .09 + syl * .135;
    WORDS.push({ w, s: clock, e: clock + d, syl, who, p });
    clock += d + .05;
    if (/[,;]$/.test(w)) clock += .2;
    else if (/[.?!]$/.test(w)) clock += .44;
  });
});
const DUR = Math.ceil(clock + .6);
const SR = 60, env = new Float32Array(Math.ceil(DUR * SR) + 1);
for (let i = 0; i < env.length; i++) env[i] = .03 + .025 * rnd(i);
WORDS.forEach((W, k) => {
  const amp = (W.who === 'T' ? .86 : .72) * (.72 + .28 * rnd(k + 7));
  for (let i = Math.floor(W.s * SR); i <= Math.ceil(W.e * SR); i++) {
