@property --mmd-spin-sweep {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

/* Re-theme with --mmd-spin-bg, -ink and -accent. */
.mmd-spin {
  --mmd-spin-bg: oklch(0.955 0.008 235);
  --mmd-spin-ink: oklch(0.25 0.02 250);
  --mmd-spin-accent: oklch(0.6 0.13 42);

  --mmd-spin-paper: color-mix(in oklch, var(--mmd-spin-bg) 40%, white);
  --mmd-spin-dim: color-mix(in oklch, var(--mmd-spin-ink) 55%, var(--mmd-spin-bg));
  --mmd-spin-line: color-mix(in oklch, var(--mmd-spin-ink) 12%, transparent);
  --mmd-spin-raise: color-mix(in oklch, var(--mmd-spin-ink) 6%, var(--mmd-spin-paper));
  --mmd-spin-ease: cubic-bezier(.22, 1, .36, 1);
  --mmd-spin-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "stage" "dial" "foot";
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 14px;
  border-radius: 20px;
  background: var(--mmd-spin-paper);
  color: var(--mmd-spin-ink);
  box-shadow: 0 0 0 1px var(--mmd-spin-line), 0 22px 44px -30px oklch(0.25 0.03 250 / .5);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mmd-spin { --mmd-spin-spring: cubic-bezier(.3, 1.4, .5, 1); }
}
:where(.mmd-spin) *, :where(.mmd-spin) *::before, :where(.mmd-spin) *::after { box-sizing: border-box; }
:where(.mmd-spin) :is(p, h3) { margin: 0; }
:where(.mmd-spin) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mmd-spin) :focus-visible { outline: 2px solid var(--mmd-spin-accent); outline-offset: 2px; }
.mmd-spin svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.mmd-spin__head {
  grid-area: head; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 10px; margin-bottom: 10px;
  & div > p { font-size: 10px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--mmd-spin-accent); }
  & h3 { font-size: clamp(16px, 5.4cqi, 20px); font-weight: 720; letter-spacing: -.02em; line-height: 1.1; text-wrap: balance; }
}
.mmd-spin__price {
  display: grid; justify-items: end; line-height: 1.2;
  & b { font-size: 15px; font-weight: 700; font-variant-numeric: tabular-nums; }
  & span { font-size: 11px; color: var(--mmd-spin-dim); white-space: nowrap; }
}

/* ---------- stage ---------- */
.mmd-spin__stage {
  grid-area: stage; position: relative; overflow: hidden;
  aspect-ratio: 5 / 4; border-radius: 14px;
  background:
    radial-gradient(70% 55% at 50% 42%, white, transparent 70%),
    linear-gradient(to bottom, var(--mmd-spin-bg) 62%, color-mix(in oklch, var(--mmd-spin-bg) 90%, var(--mmd-spin-ink)));
  cursor: grab; touch-action: pan-y; outline: none;
  &:focus-visible { box-shadow: 0 0 0 2px var(--mmd-spin-paper), 0 0 0 4px var(--mmd-spin-accent); }
  &[data-drag] { cursor: grabbing; }
  &[aria-disabled="true"] { cursor: progress; }
}
.mmd-spin__cv { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.mmd-spin__dot {
  position: absolute; left: -11px; top: -11px; width: 22px; height: 22px; border-radius: 50%;
  display: grid; place-items: center; cursor: pointer;
  opacity: 0; scale: .4; pointer-events: none;
  transition: opacity .25s linear, scale .4s var(--mmd-spin-spring);
  &::before { content: ""; width: 10px; height: 10px; border-radius: 50%; background: var(--mmd-spin-paper); box-shadow: 0 0 0 3px var(--mmd-spin-accent), 0 2px 6px oklch(0.2 0.03 250 / .4); }
  &::after {
    content: ""; position: absolute; inset: 0; border-radius: 50%; border: 2px solid var(--mmd-spin-accent);
    animation: mmd-spin-ping 2.2s cubic-bezier(.2, .6, .3, 1) infinite;
  }
  &[data-show] { opacity: 1; scale: 1; pointer-events: auto; }
  &[data-open]::before { background: var(--mmd-spin-accent); }
}
@keyframes mmd-spin-ping { from { opacity: .7; transform: scale(.5); } 70%, to { opacity: 0; transform: scale(1.5); } }
.mmd-spin__load {
  position: absolute; left: 50%; bottom: 12px; translate: -50% 0;
  display: flex; align-items: center; gap: 8px; padding: 6px 12px 6px 7px; border-radius: 999px;
  background: var(--mmd-spin-paper); box-shadow: 0 0 0 1px var(--mmd-spin-line), 0 6px 18px -8px oklch(0.25 0.03 250 / .4);
  font-size: 11.5px; font-weight: 600; white-space: nowrap; pointer-events: none;
  transition: opacity .3s linear, translate .4s var(--mmd-spin-ease);
  & i {
    width: 16px; height: 16px; border-radius: 50%;
    background: conic-gradient(from var(--mmd-spin-sweep), transparent 25%, var(--mmd-spin-accent));
    -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 2.5px), #000 calc(100% - 2px));
    mask: radial-gradient(farthest-side, transparent calc(100% - 2.5px), #000 calc(100% - 2px));
    animation: mmd-spin-sweep .8s linear infinite;
  }
  & b { font-weight: 650; font-family: ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
}
@keyframes mmd-spin-sweep { to { --mmd-spin-sweep: 360deg; } }
.mmd-spin:not([data-state="loading"]) .mmd-spin__load { opacity: 0; translate: -50% 8px; & i { animation: none; } }
.mmd-spin__hint {
  position: absolute; left: 50%; bottom: 12px; translate: -50% 0;
  display: flex; align-items: center; gap: 6px; padding: 5px 11px 5px 8px; border-radius: 999px;
  background: color-mix(in oklch, var(--mmd-spin-ink) 82%, transparent); color: var(--mmd-spin-paper);
  font-size: 11.5px; font-weight: 600; white-space: nowrap; pointer-events: none;
  opacity: 0; transition: opacity .3s linear, translate .45s var(--mmd-spin-ease);
  & svg { width: 16px; height: 16px; animation: mmd-spin-sway 1.6s ease-in-out infinite; }
}
.mmd-spin[data-state="ready"]:not([data-touched]) .mmd-spin__hint { opacity: 1; transition-delay: .5s; }
.mmd-spin[data-touched] .mmd-spin__hint { translate: -50% 8px; }
@keyframes mmd-spin-sway { 50% { transform: translateX(2px); } }
.mmd-spin__note {
  position: absolute; left: 10px; right: 10px; bottom: 10px; z-index: 3;
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; align-items: start;
  padding: 8px 5px 9px 11px; border-radius: 12px;
  background: var(--mmd-spin-paper); box-shadow: 0 0 0 1px var(--mmd-spin-line), 0 14px 30px -14px oklch(0.25 0.03 250 / .55);
  opacity: 0; translate: 0 10px; pointer-events: none;
