/* Re-theme with --mmd-pip-paper, -ink, -accent (page) and -screen (player chrome). */
.mmd-pip {
  --mmd-pip-paper: oklch(0.984 0.005 85);
  --mmd-pip-ink: oklch(0.23 0.012 30);
  --mmd-pip-accent: oklch(0.55 0.19 25);
  --mmd-pip-screen: oklch(0.19 0.015 310);

  --mmd-pip-dim: color-mix(in oklch, var(--mmd-pip-ink) 58%, var(--mmd-pip-paper));
  --mmd-pip-line: color-mix(in oklch, var(--mmd-pip-ink) 11%, transparent);
  --mmd-pip-raise: color-mix(in oklch, var(--mmd-pip-ink) 5%, var(--mmd-pip-paper));
