:where(.mmd-pip) :is(p, h3) { margin: 0; }
:where(.mmd-pip) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mmd-pip) :focus-visible { outline: 2px solid var(--mmd-pip-accent); outline-offset: 2px; }
.mmd-pip svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; flex: none; }

/* ---------- the page underneath ---------- */
.mmd-pip__page {
  position: absolute; inset: 0; overflow-y: auto; overscroll-behavior: contain;
  scrollbar-width: thin; scrollbar-color: var(--mmd-pip-line) transparent;
  &:focus-visible { outline-offset: -3px; border-radius: 18px; }
  & article { padding: 14px 18px 96px; display: grid; gap: 10px; }
  & article > p:not([class]) { font-size: 13.5px; line-height: 1.62; text-wrap: pretty; color: color-mix(in oklch, var(--mmd-pip-ink) 88%, var(--mmd-pip-paper)); }
  & h3 { font-size: clamp(19px, 6.4cqi, 24px); line-height: 1.12; font-weight: 760; letter-spacing: -.025em; text-wrap: balance; }
}
