/* Re-theme with --mmd-queue-bg, -fg and -accent. */
.mmd-queue {
  --mmd-queue-bg: oklch(0.205 0.035 18);
  --mmd-queue-fg: oklch(0.95 0.02 80);
  --mmd-queue-accent: oklch(0.81 0.12 80);

  --mmd-queue-dim: color-mix(in oklch, var(--mmd-queue-fg) 56%, var(--mmd-queue-bg));
  --mmd-queue-faint: color-mix(in oklch, var(--mmd-queue-fg) 34%, var(--mmd-queue-bg));
  --mmd-queue-line: color-mix(in oklch, var(--mmd-queue-fg) 10%, transparent);
  --mmd-queue-raise: color-mix(in oklch, var(--mmd-queue-fg) 7%, var(--mmd-queue-bg));
  --mmd-queue-lift: color-mix(in oklch, var(--mmd-queue-fg) 12%, var(--mmd-queue-bg));
  --mmd-queue-ease: cubic-bezier(.22, 1, .36, 1);
  --mmd-queue-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "now" "head" "list";
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  height: 448px;
  padding: 14px 12px 8px;
  border-radius: 18px;
  overflow: hidden;
  overflow: clip;
  background:
    radial-gradient(120% 60% at 0% 0%, color-mix(in oklch, var(--mmd-queue-np, var(--mmd-queue-accent)) 16%, transparent), transparent 70%),
    var(--mmd-queue-bg);
  color: var(--mmd-queue-fg);
  box-shadow: inset 0 0 0 1px var(--mmd-queue-line);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  transition: background-color .4s;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mmd-queue { --mmd-queue-spring: cubic-bezier(.3, 1.4, .5, 1); }
}
:where(.mmd-queue) *, :where(.mmd-queue) *::before, :where(.mmd-queue) *::after { box-sizing: border-box; }
:where(.mmd-queue) :is(p, h3, h4, ol) { margin: 0; padding: 0; }
:where(.mmd-queue) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mmd-queue) :focus-visible { outline: 2px solid var(--mmd-queue-accent); outline-offset: 2px; }
.mmd-queue svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

/* ---------- generated cover art ---------- */
.mmd-queue__art {
  --h: 30;
  display: block; aspect-ratio: 1; border-radius: 6px; position: relative; overflow: hidden;
  box-shadow: inset 0 0 0 1px oklch(1 0 0 / .08);
  background: linear-gradient(160deg, oklch(0.56 0.12 var(--h)), oklch(0.27 0.07 calc(var(--h) + 30)));
}
.mmd-queue__art[data-k="0"] { background: radial-gradient(circle at 68% 32%, oklch(0.88 0.12 calc(var(--h) + 50)) 0 17%, transparent 18%), linear-gradient(170deg, oklch(0.6 0.13 var(--h)) 0 58%, oklch(0.3 0.08 calc(var(--h) + 40)) 58%); }
.mmd-queue__art[data-k="1"] { background: repeating-linear-gradient(0deg, oklch(0.78 0.11 var(--h)) 0 2px, transparent 2px 6px) 0 100% / 100% 46% no-repeat, linear-gradient(oklch(0.42 0.1 calc(var(--h) + 20)), oklch(0.22 0.06 var(--h))); }
.mmd-queue__art[data-k="2"] { background: repeating-radial-gradient(circle at 50% 115%, oklch(0.74 0.12 var(--h)) 0 2px, oklch(0.32 0.09 calc(var(--h) - 20)) 2px 7px); }
.mmd-queue__art[data-k="3"] { background: conic-gradient(from 210deg at 35% 70%, oklch(0.72 0.14 var(--h)), oklch(0.38 0.1 calc(var(--h) + 70)), oklch(0.72 0.14 var(--h))); }

/* ---------- now playing ---------- */
.mmd-queue__now {
  grid-area: now;
  display: grid; grid-template-columns: 68px minmax(0, 1fr) auto; grid-template-areas: "art np np" "art prog tp";
  column-gap: 12px; row-gap: 6px; align-items: center; padding: 0 2px 12px;
}
.mmd-queue__big { grid-area: art; width: 68px; border-radius: 9px; box-shadow: 0 10px 24px -10px oklch(0.05 0.02 20 / .8), inset 0 0 0 1px oklch(1 0 0 / .1); }
.mmd-queue__np { grid-area: np; min-width: 0; align-self: end; }
.mmd-queue__eyebrow {
  display: flex; align-items: center; gap: 6px;
  font-size: 10px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--mmd-queue-accent);
}
.mmd-queue__eq {
  display: inline-flex; align-items: end; gap: 1.5px; height: 10px;
  & i { width: 2.5px; height: 100%; border-radius: 1px; background: currentColor; transform-origin: 50% 100%; animation: mmd-queue-eq .9s ease-in-out infinite alternate; }
  & i:nth-child(2) { animation-duration: .7s; animation-delay: -.3s; }
  & i:nth-child(3) { animation-duration: 1.1s; animation-delay: -.5s; }
}
@keyframes mmd-queue-eq { 0% { transform: scaleY(.25); } 100% { transform: scaleY(1); } }
.mmd-queue:not([data-state="playing"]) .mmd-queue__eq i { animation-play-state: paused; }
.mmd-queue[data-state="ended"] .mmd-queue__eq { display: none; }
.mmd-queue__np h3 { margin-top: 2px; font-size: clamp(14.5px, 4.6cqi, 17px); font-weight: 700; letter-spacing: -.015em; line-height: 1.2; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mmd-queue__by { font-size: 12px; color: var(--mmd-queue-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mmd-queue__prog {
  grid-area: prog; display: grid; grid-template-columns: auto 1fr; row-gap: 3px; align-self: start;
  font: 500 10.5px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mmd-queue-dim);
  & [data-rem] { justify-self: end; }
}
.mmd-queue__bar {
  grid-column: 1 / -1; height: 3px; border-radius: 2px; overflow: hidden; background: var(--mmd-queue-line);
  & i { display: block; height: 100%; background: var(--mmd-queue-fg); transform-origin: 0 50%; transform: scaleX(var(--p, 0)); }
}
.mmd-queue__transport {
  grid-area: tp; display: flex; align-items: center; gap: 2px; align-self: start; margin-top: -6px;
  & button { width: 30px; height: 30px; display: grid; place-items: center; border-radius: 50%; color: var(--mmd-queue-dim); transition: color .15s, background-color .15s, scale .25s var(--mmd-queue-spring); }
  & button:hover:not(:disabled) { color: var(--mmd-queue-fg); background: var(--mmd-queue-raise); }
  & button:active:not(:disabled) { scale: .9; }
  & button:disabled { opacity: .35; cursor: default; }
  & svg { width: 16px; height: 16px; }
  & path:not([class]) { fill: currentColor; }
}
.mmd-queue__play {
  width: 34px !important; height: 34px !important; color: var(--mmd-queue-bg) !important; background: var(--mmd-queue-fg) !important;
  & .mmd-queue__gplay { display: none; fill: currentColor; stroke-width: 1.2; }
  & .mmd-queue__gpause { stroke-width: 2.6; }
}
.mmd-queue:not([data-state="playing"]) .mmd-queue__play {
  & .mmd-queue__gplay { display: block; }
  & .mmd-queue__gpause { display: none; }
}

/* ---------- list ---------- */
.mmd-queue__head {
  grid-area: head; display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 8px;
  & .mmd-queue__title { display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 8px; row-gap: 3px; min-width: 0; }
  padding: 10px 2px 8px; border-top: 1px solid var(--mmd-queue-line);
  & h4 { font-size: 12px; font-weight: 750; letter-spacing: .08em; text-transform: uppercase; }
  & p { font: 500 11px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mmd-queue-dim); white-space: nowrap; }
}
.mmd-queue__tool {
  display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 9px; border-radius: 999px;
  font-size: 11.5px; font-weight: 600; color: var(--mmd-queue-dim); box-shadow: inset 0 0 0 1px var(--mmd-queue-line);
  transition: color .15s, background-color .15s;
  & svg { width: 14px; height: 14px; }
  &:hover:not(:disabled) { color: var(--mmd-queue-fg); background: var(--mmd-queue-raise); }
  &:disabled { opacity: .35; cursor: default; }
}
.mmd-queue__scroll {
  grid-area: list; position: relative; min-height: 0; overflow-y: auto; overscroll-behavior: contain;
  margin: 0 -6px; padding: 0 6px 56px;
  scrollbar-width: thin; scrollbar-color: var(--mmd-queue-line) transparent;
}
.mmd-queue__list { list-style: none; display: grid; gap: 2px; }
.mmd-queue__row {
  position: relative; height: 50px;
  display: grid; grid-template-columns: 18px 36px minmax(0, 1fr) auto 28px; align-items: center; gap: 9px;
  padding: 0 4px 0 2px; border-radius: 10px; cursor: default; outline: none;
  transition: background-color .15s;
  &:hover { background: var(--mmd-queue-raise); }
  &:focus-visible { box-shadow: inset 0 0 0 2px var(--mmd-queue-accent); }
  & > time { font: 500 11.5px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mmd-queue-dim); }
}
@supports (animation-timeline: view()) {
  .mmd-queue__row { animation: mmd-queue-enter linear both; animation-timeline: view(); animation-range: entry 0% entry 90%; }
}
@keyframes mmd-queue-enter { from { opacity: .2; scale: .96; } }
.mmd-queue__grip {
  display: grid; place-items: center; height: 100%; color: var(--mmd-queue-faint); cursor: grab; touch-action: none;
  & svg { width: 14px; height: 14px; fill: currentColor; stroke: none; }
  &:hover { color: var(--mmd-queue-fg); }
}
.mmd-queue__thumb {
  position: relative; width: 36px; padding: 0; border-radius: 6px;
  & .mmd-queue__art { width: 36px; }
  & svg {
    position: absolute; inset: 0; width: 100%; height: 100%; padding: 9px; border-radius: 6px;
    background: oklch(0.1 0.02 20 / .55); color: white; fill: currentColor; stroke: none;
    opacity: 0; scale: .9; transition: opacity .15s, scale .25s var(--mmd-queue-spring);
  }
  &:hover svg, &:focus-visible svg { opacity: 1; scale: 1; }
}
.mmd-queue__meta {
  display: grid; min-width: 0; line-height: 1.25;
  & b { font-size: 13px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & span { font-size: 11.5px; color: var(--mmd-queue-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.mmd-queue__x {
  width: 28px; height: 28px; display: grid; place-items: center; border-radius: 8px; color: var(--mmd-queue-faint);
  opacity: 0; transition: opacity .15s, color .15s, background-color .15s;
  & svg { width: 15px; height: 15px; }
  &:hover { color: var(--mmd-queue-fg); background: var(--mmd-queue-lift); }
}
.mmd-queue__row:is(:hover, :focus-visible, :focus-within) .mmd-queue__x { opacity: 1; }
@media (hover: none) { .mmd-queue__x { opacity: .7; } }

/* drag + grab */
.mmd-queue[data-dragging] {
  & .mmd-queue__row { transition: transform .26s var(--mmd-queue-ease), background-color .15s; }
  & .mmd-queue__row:hover { background: none; }
  & .mmd-queue__grip { cursor: grabbing; }
}
.mmd-queue__row[data-lift] {
  z-index: 2; transition: none !important; background: var(--mmd-queue-lift) !important;
  box-shadow: 0 14px 30px -12px oklch(0.05 0.02 20 / .9), inset 0 0 0 1px var(--mmd-queue-line);
  scale: 1.02;
}
.mmd-queue__row[aria-grabbed="true"] { background: var(--mmd-queue-lift); box-shadow: inset 0 0 0 2px var(--mmd-queue-accent), 0 10px 24px -12px oklch(0.05 0.02 20 / .9); }
.mmd-queue.is-settling .mmd-queue__row { transition: none !important; }

/* empty */
.mmd-queue__empty {
  display: none; justify-items: center; text-align: center; gap: 6px; padding: 20px 18px 0;
  & svg { width: 44px; height: 44px; color: var(--mmd-queue-faint); stroke-width: 2; margin-bottom: 4px; }
  & b { font-size: 14px; font-weight: 700; }
  & p { font-size: 12px; color: var(--mmd-queue-dim); max-width: 30ch; text-wrap: balance; }
  & button { margin-top: 8px; height: 32px; padding: 0 14px; border-radius: 999px; background: var(--mmd-queue-accent); color: var(--mmd-queue-bg); font-size: 12.5px; font-weight: 700; transition: scale .25s var(--mmd-queue-spring); }
  & button:active { scale: .95; }
}
.mmd-queue[data-empty] .mmd-queue__empty {
  display: grid;
  @starting-style { opacity: 0; translate: 0 8px; }
  transition: opacity .3s .1s, translate .45s .1s var(--mmd-queue-ease);
}

/* toast */
.mmd-queue__toast {
  position: absolute; left: 12px; right: 12px; bottom: 10px; z-index: 5;
  display: none; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding: 6px 6px 6px 12px; border-radius: 12px;
  background: var(--mmd-queue-fg); color: var(--mmd-queue-bg);
  font-size: 12px; font-weight: 550;
  box-shadow: 0 16px 34px -12px oklch(0.05 0.02 20 / .9);
  opacity: 0; translate: 0 10px;
  transition: opacity .2s linear, translate .4s var(--mmd-queue-ease), display .4s allow-discrete;
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & button { height: 28px; padding: 0 12px; border-radius: 8px; font-weight: 700; color: color-mix(in oklch, var(--mmd-queue-accent) 45%, var(--mmd-queue-bg)); }
  & button:hover { background: color-mix(in oklch, var(--mmd-queue-bg) 10%, transparent); }
  &[data-open] { display: grid; opacity: 1; translate: 0 0; }
}
@starting-style { .mmd-queue__toast[data-open] { opacity: 0; translate: 0 10px; } }
.mmd-queue__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (width < 340px) {
  .mmd-queue__now { grid-template-columns: 56px minmax(0, 1fr) auto; column-gap: 10px; }
  .mmd-queue__big { width: 56px; }
  .mmd-queue__tool[data-act="shuffle"] { padding: 0 7px; font-size: 0; gap: 0; }
  .mmd-queue__tool[data-act="shuffle"] svg { width: 15px; height: 15px; }
  .mmd-queue__row { grid-template-columns: 16px 34px minmax(0, 1fr) auto 26px; gap: 7px; }
}

@media (prefers-reduced-motion: reduce) {
  .mmd-queue *, .mmd-queue *::before, .mmd-queue *::after { transition-duration: .01ms !important; transition-delay: 0s !important; }
  .mmd-queue__eq i { animation: none; transform: scaleY(.6); }
  .mmd-queue__eq i:nth-child(2) { transform: scaleY(1); }
  .mmd-queue__row { animation: none; }
  .mmd-queue__row[data-lift] { scale: 1; }
}

