const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1)';
const EASE = 'cubic-bezier(.22, 1, .36, 1)';
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const fmt = (s) => { s = Math.max(0, Math.round(s)); const h = Math.floor(s / 3600), m = Math.floor(s / 60) % 60, r = String(s % 60).padStart(2, '0'); return h ? h + ':' + String(m).padStart(2, '0') + ':' + r : m + ':' + r; };
const esc = (t) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;');

/* ---------- library ---------- */
const LIB = [
  ['Harbour Lights (Live)', 'Okafor & the Late Trains', 252, 24, 0],
  ['Signal Box', 'Okafor & the Late Trains', 221, 40, 1],
  ['Paper Moons', 'Juniper Vale', 185, 300, 0],
  ['Night Bus to Ostend', 'The Quiet Hours', 267, 250, 2],
  ['Saltwater Hymn', 'Marisol Okeke', 178, 190, 3],
  ['Third Platform', 'Hollis Grey', 213, 60, 2],
  ['Kettle & Rain', 'Ada Brightwater', 166, 150, 1],
  ['Copper Sky', 'Juniper Vale', 199, 70, 3],
  ['Last Ferry', 'The Quiet Hours', 302, 220, 0]
].map(([t, a, d, h, k], i) => ({ id: 't' + i, t, a, d, h, k }));

let now = LIB[0], queue = LIB.slice(1), hist = [];
let elapsed = 67, playing = true, ended = false, raf = 0, last = 0, visible = true, shownSec = -1;
let drag = null, grab = null, removed = null, toastT = 0, active = null, moving = false;

const list = $('.mmd-queue__list'), scroller = $('.mmd-queue__scroll'), bigArt = $('.mmd-queue__big');
const toast = $('.mmd-queue__toast'), live = $('.mmd-queue__sr');
const say = (m) => { live.textContent = ''; later(30, () => { live.textContent = m; }); };
const GRIP = '<svg viewBox="0 0 24 24"><circle cx="9" cy="6" r="1.6"/><circle cx="15" cy="6" r="1.6"/><circle cx="9" cy="12" r="1.6"/><circle cx="15" cy="12" r="1.6"/><circle cx="9" cy="18" r="1.6"/><circle cx="15" cy="18" r="1.6"/></svg>';
const X = '<svg viewBox="0 0 24 24"><path d="M7 7l10 10M17 7 7 17"/></svg>';

function rowFor(tr) {
  const li = document.createElement('li');
  li.className = 'mmd-queue__row';
  li.dataset.id = tr.id;
  li.tabIndex = -1;
  li.innerHTML =
    '<span class="mmd-queue__grip" aria-hidden="true">' + GRIP + '</span>' +
    '<button type="button" class="mmd-queue__thumb" tabindex="-1" aria-label="Play ' + esc(tr.t) + ' now"><span class="mmd-queue__art" data-k="' + tr.k + '" style="--h:' + tr.h + '"></span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 7v10l8-5z"/></svg></button>' +
    '<span class="mmd-queue__meta"><b>' + esc(tr.t) + '</b><span>' + esc(tr.a) + '</span></span>' +
    '<time>' + fmt(tr.d) + '</time>' +
    '<button type="button" class="mmd-queue__x" tabindex="-1" aria-label="Remove ' + esc(tr.t) + '">' + X + '</button>';
  return li;
}
const rows = () => $$('.mmd-queue__row', list);
const rowEl = (tr) => list.querySelector('[data-id="' + tr.id + '"]');
const byId = (id) => LIB.find((t) => t.id === id);

function sync() {
  const total = queue.reduce((s, t) => s + t.d, 0);
  $('[data-sum]').textContent = queue.length ? queue.length + (queue.length === 1 ? ' song · ' : ' songs · ') + fmt(total) : 'Empty';
  root.toggleAttribute('data-empty', !queue.length);
  $('[data-act="shuffle"]').disabled = queue.length < 2;
  $('[data-act="clear"]').disabled = !queue.length;
  $('[data-act="next"]').disabled = !queue.length;
  rows().forEach((li, i) => {
    const t = byId(li.dataset.id);
    li.setAttribute('aria-label', t.t + ', ' + t.a + ', ' + fmt(t.d) + ', ' + (i + 1) + ' of ' + queue.length);
  });
  if (!active || !active.isConnected) active = rows()[0] || null;
  rows().forEach((li) => { li.tabIndex = li === active ? 0 : -1; });
}
function renderNow() {
  bigArt.dataset.k = now.k;
  bigArt.style.setProperty('--h', now.h);
  root.style.setProperty('--mmd-queue-np', 'oklch(0.7 0.13 ' + now.h + ')');
  $('[data-np-title]').textContent = now.t;
  $('[data-np-artist]').textContent = now.a;
  shownSec = -1;
  progress();
}
function progress() {
  const s = Math.floor(elapsed);
  $('.mmd-queue__bar').style.setProperty('--p', clamp(elapsed / now.d, 0, 1));
  if (s === shownSec) return;
  shownSec = s;
  $('[data-el]').textContent = fmt(elapsed);
  $('[data-rem]').textContent = '-' + fmt(now.d - elapsed);
}
function setPlaying(on) {
  playing = on && !ended;
  root.dataset.state = ended ? 'ended' : playing ? 'playing' : 'paused';
  $('[data-act="play"]').setAttribute('aria-label', playing ? 'Pause' : 'Play');
  $('[data-np-label]').textContent = ended ? 'End of queue' : playing ? 'Now playing' : 'Paused';
  kick();
}

/* ---------- FLIP ---------- */
function flip(mutate, opts = {}) {
  const before = new Map(rows().map((el) => [el, el.getBoundingClientRect()]));
  mutate();
  if (RM.matches) return;
  rows().forEach((el, i) => {
    const b = before.get(el);
    if (!b) return;
    const a = el.getBoundingClientRect(), dy = b.top - a.top;
    if (Math.abs(dy) < .5) return;
    el.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }],
      { duration: opts.duration || 420, easing: opts.easing || SPRING, delay: opts.stagger ? i * opts.stagger : 0, fill: 'backwards' });
  });
}

/* ---------- play order ---------- */
function playAt(idx, why) {
  const tr = queue[idx];
  if (!tr) return;
  const el = rowEl(tr), from = el ? $('.mmd-queue__art', el).getBoundingClientRect() : null;
  const sr = scroller.getBoundingClientRect();
  const fromVisible = from && from.bottom > sr.top && from.top < sr.bottom;
  const focusNext = el && el.contains(document.activeElement);
  flip(() => {
    hist.push(now);
    now = queue.splice(idx, 1)[0];
    if (el) el.remove();
    elapsed = 0; ended = false;
    renderNow();
    sync();
  });
  if (!RM.matches) {
    const to = bigArt.getBoundingClientRect();
    if (fromVisible) {
      bigArt.animate([
        { transform: 'translate(' + (from.left - to.left) + 'px,' + (from.top - to.top) + 'px) scale(' + from.width / to.width + ')', borderRadius: '6px' },
        { transform: 'none', borderRadius: '9px' }
      ], { duration: 560, easing: SPRING });
    } else bigArt.animate([{ opacity: 0, transform: 'scale(.85)' }, { opacity: 1, transform: 'none' }], { duration: 380, easing: EASE });
    $('.mmd-queue__np').animate([{ opacity: 0, transform: 'translateY(6px)' }, { opacity: 1, transform: 'none' }], { duration: 360, easing: EASE });
  }
  setPlaying(true);
  if (focusNext) { const r = rows()[Math.min(idx, rows().length - 1)]; active = r || null; sync(); (r || $('[data-act="play"]')).focus({ preventScroll: true }); }
  say((why || 'Now playing') + ': ' + now.t + ' by ' + now.a);
}
function prev() {
  if (elapsed > 3 || !hist.length) { elapsed = 0; ended = false; progress(); setPlaying(true); say('Restarted ' + now.t); return; }
  flip(() => {
    queue.unshift(now);
    list.prepend(rowFor(now));
    now = hist.pop();
    elapsed = 0; ended = false;
    renderNow(); sync();
  });
  if (!RM.matches) rows()[0].animate([{ opacity: 0, transform: 'translateY(-10px)' }, { opacity: 1, transform: 'none' }], { duration: 360, easing: EASE });
  setPlaying(true);
  say('Back to ' + now.t);
}
function moveRow(tr, to, announce) {
  const from = queue.indexOf(tr);
  to = clamp(to, 0, queue.length - 1);
  if (from === to) return;
  moving = true;
  flip(() => {
    queue.splice(from, 1);
    queue.splice(to, 0, tr);
    const el = rowEl(tr), ref = rows().filter((r) => r !== el)[to];
    list.insertBefore(el, ref || null);
    sync();
  }, { duration: 320, easing: EASE });
  moving = false;
  if (announce) say(tr.t + ', position ' + (to + 1) + ' of ' + queue.length);
}
function shuffle() {
  const a = queue.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  if (a.every((t, i) => t === queue[i])) a.push(a.shift());
  flip(() => {
    queue = a;
    queue.forEach((t) => list.append(rowEl(t)));
    sync();
  }, { stagger: 22, duration: 520 });
  say('Queue shuffled');
}

/* ---------- remove / clear / undo ---------- */
function showToast(msg) {
  $('[data-toast]').textContent = msg;
  toast.setAttribute('data-open', '');
  clearTimeout(toastT);
  toastT = later(6000, () => toast.removeAttribute('data-open'));
}
function remove(tr) {
  const i = queue.indexOf(tr), el = rowEl(tr);
  if (i < 0) return;
  const hadFocus = el.contains(document.activeElement);
  removed = { items: [[tr, i]] };
  const done = () => {
    flip(() => { el.remove(); queue.splice(queue.indexOf(tr), 1); sync(); }, { duration: 300, easing: EASE });
    if (hadFocus) { const r = rows()[Math.min(i, rows().length - 1)]; active = r || null; sync(); (r || $('[data-act="fill"]')).focus({ preventScroll: true }); }
  };
  if (RM.matches) done();
  else el.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateX(24px)' }], { duration: 180, easing: 'ease-in', fill: 'forwards' }).onfinish = () => { if (root.isConnected) done(); };
  showToast('Removed “' + tr.t + '”');
  say('Removed ' + tr.t + '. Undo is available.');
}
function clearAll() {
  if (!queue.length) return;
  removed = { items: queue.map((t, i) => [t, i]) };
  const n = queue.length;
  const els = rows();
  const done = () => { queue = []; list.textContent = ''; sync(); $('[data-act="fill"]').focus({ preventScroll: true }); };
  if (RM.matches) done();
  else {
    els.forEach((el, i) => el.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateX(20px)' }], { duration: 200, delay: i * 28, easing: 'ease-in', fill: 'forwards' }));
    later(200 + els.length * 28, done);
  }
  showToast('Cleared ' + n + ' songs');
  say('Queue cleared. Undo is available.');
}
function undo() {
  if (!removed) return;
  const items = removed.items;
  removed = null;
  toast.removeAttribute('data-open');
  flip(() => {
    for (const [tr, i] of items.sort((a, b) => a[1] - b[1])) {
      if (queue.includes(tr)) continue;
      const at = Math.min(i, queue.length);
      queue.splice(at, 0, tr);
      list.insertBefore(rowFor(tr), rows()[at] || null);
    }
    sync();
  }, { duration: 340, easing: EASE });
  if (!RM.matches) items.forEach(([tr], k) => { const el = rowEl(tr); if (el) el.animate([{ opacity: 0, transform: 'translateX(-14px)' }, { opacity: 1, transform: 'none' }], { duration: 320, delay: k * 24, easing: EASE, fill: 'backwards' }); });
  const first = rowEl(items[0][0]);
  if (first) { active = first; sync(); first.focus({ preventScroll: true }); }
  say('Restored ' + (items.length === 1 ? items[0][0].t : items.length + ' songs'));
}
function fill() {
  const fresh = LIB.filter((t) => t !== now && !queue.includes(t)).slice(0, 8);
  fresh.forEach((t, i) => {
    queue.push(t);
    const li = rowFor(t);
    list.append(li);
    if (!RM.matches) li.animate([{ opacity: 0, transform: 'translateY(10px)' }, { opacity: 1, transform: 'none' }], { duration: 380, delay: i * 40, easing: EASE, fill: 'backwards' });
  });
  if (ended) { ended = false; }
  active = rows()[0] || null;
  sync();
  if (active) active.focus({ preventScroll: true });
  say('Queued ' + fresh.length + ' songs');
}

/* ---------- pointer drag (grip) ---------- */
list.addEventListener('pointerdown', (e) => {
  const grip = e.target.closest('.mmd-queue__grip');
  if (!grip || e.button || grab) return;
  const row = grip.closest('.mmd-queue__row'), all = rows();
  const H = row.getBoundingClientRect().height + parseFloat(getComputedStyle(list).rowGap || 0);
  drag = { row, all, from: all.indexOf(row), to: all.indexOf(row), y0: e.clientY, s0: scroller.scrollTop, H, py: e.clientY };
  row.setAttribute('data-lift', '');
  root.setAttribute('data-dragging', '');
  grip.setPointerCapture(e.pointerId);
  e.preventDefault();
});
function dragMove(clientY) {
  const d = drag;
  const dy = clientY - d.y0 + (scroller.scrollTop - d.s0);
  d.row.style.transform = 'translateY(' + dy + 'px)';
  const to = clamp(d.from + Math.round(dy / d.H), 0, d.all.length - 1);
  if (to === d.to) return;
  d.to = to;
  d.all.forEach((el, i) => {
    if (el === d.row) return;
    let sh = 0;
    if (d.from < to && i > d.from && i <= to) sh = -d.H;
    if (d.from > to && i >= to && i < d.from) sh = d.H;
    el.style.transform = sh ? 'translateY(' + sh + 'px)' : '';
  });
}
list.addEventListener('pointermove', (e) => {
  if (!drag) return;
  drag.py = e.clientY;
  const sr = scroller.getBoundingClientRect();
  if (e.clientY < sr.top + 28) scroller.scrollTop -= 6;
  else if (e.clientY > sr.bottom - 28) scroller.scrollTop += 6;
  dragMove(e.clientY);
});
const drop = () => {
  if (!drag) return;
  const d = drag;
  drag = null;
  const tr = byId(d.row.dataset.id), rect0 = d.row.getBoundingClientRect();
  root.classList.add('is-settling');
  d.all.forEach((el) => { el.style.transform = ''; });
  root.removeAttribute('data-dragging');
  if (d.to !== d.from) {
    queue.splice(d.from, 1);
    queue.splice(d.to, 0, tr);
    const ref = rows().filter((r) => r !== d.row)[d.to];
    list.insertBefore(d.row, ref || null);
    sync();
    say(tr.t + ' moved to position ' + (d.to + 1) + ' of ' + queue.length);
  }
  const rect1 = d.row.getBoundingClientRect();
  void list.offsetWidth;
  root.classList.remove('is-settling');
  if (!RM.matches) d.row.animate([{ transform: 'translateY(' + (rect0.top - rect1.top) + 'px)', scale: 1.02 }, { transform: 'none', scale: 1 }], { duration: 380, easing: SPRING });
  d.row.removeAttribute('data-lift');
  active = d.row; sync();
};
list.addEventListener('pointerup', drop);
list.addEventListener('pointercancel', drop);

/* ---------- keyboard ---------- */
function focusRow(el) { if (!el) return; active = el; sync(); el.focus({ preventScroll: false }); }
list.addEventListener('keydown', (e) => {
  const row = e.target.closest('.mmd-queue__row');
  if (!row || e.target !== row) return;
  const all = rows(), i = all.indexOf(row), tr = byId(row.dataset.id);
  const up = e.key === 'ArrowUp', down = e.key === 'ArrowDown';
  if (grab) {
    if (up || down) { e.preventDefault(); moveRow(tr, queue.indexOf(tr) + (up ? -1 : 1), true); row.focus({ preventScroll: false }); return; }
    if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); row.setAttribute('aria-grabbed', 'false'); grab = null; say('Dropped ' + tr.t + ' at position ' + (queue.indexOf(tr) + 1)); return; }
    if (e.key === 'Escape') { e.preventDefault(); moveRow(tr, grab.from, false); row.setAttribute('aria-grabbed', 'false'); grab = null; row.focus(); say('Move cancelled'); return; }
    return;
  }
  if ((up || down) && e.altKey) { e.preventDefault(); moveRow(tr, i + (up ? -1 : 1), true); row.focus({ preventScroll: false }); }
  else if (up || down) { e.preventDefault(); focusRow(all[clamp(i + (up ? -1 : 1), 0, all.length - 1)]); }
  else if (e.key === 'Home') { e.preventDefault(); focusRow(all[0]); }
  else if (e.key === 'End') { e.preventDefault(); focusRow(all[all.length - 1]); }
  else if (e.key === ' ') { e.preventDefault(); grab = { from: i }; row.setAttribute('aria-grabbed', 'true'); say('Grabbed ' + tr.t + ', position ' + (i + 1) + ' of ' + queue.length + '. Arrow keys move, Space drops, Escape cancels.'); }
  else if (e.key === 'Enter') { e.preventDefault(); playAt(i, 'Playing now'); }
  else if (e.key === 'Delete' || e.key === 'Backspace') { e.preventDefault(); remove(tr); }
});
list.addEventListener('focusout', (e) => {
  if (moving) return;
  if (grab && !list.contains(e.relatedTarget)) { const el = list.querySelector('[aria-grabbed="true"]'); if (el) el.setAttribute('aria-grabbed', 'false'); grab = null; }
});
list.addEventListener('focusin', (e) => { const r = e.target.closest('.mmd-queue__row'); if (r && r !== active) { active = r; rows().forEach((li) => { li.tabIndex = li === r ? 0 : -1; }); } });

/* ---------- clicks ---------- */
root.addEventListener('click', (e) => {
  const thumb = e.target.closest('.mmd-queue__thumb');
  if (thumb) { playAt(queue.indexOf(byId(thumb.closest('.mmd-queue__row').dataset.id)), 'Playing now'); return; }
  const x = e.target.closest('.mmd-queue__x');
  if (x) { remove(byId(x.closest('.mmd-queue__row').dataset.id)); return; }
  const b = e.target.closest('[data-act]');
  if (!b || b.disabled) return;
  const a = b.dataset.act;
  if (a === 'play') { if (ended) { if (queue.length) playAt(0); else { elapsed = 0; ended = false; progress(); setPlaying(true); } } else setPlaying(!playing); }
  else if (a === 'next') playAt(0, 'Skipped to');
  else if (a === 'prev') prev();
  else if (a === 'shuffle') shuffle();
  else if (a === 'clear') clearAll();
  else if (a === 'undo') undo();
  else if (a === 'fill') fill();
});
list.addEventListener('dblclick', (e) => {
  const r = e.target.closest('.mmd-queue__row');
  if (r && !e.target.closest('button, .mmd-queue__grip')) playAt(queue.indexOf(byId(r.dataset.id)), 'Playing now');
});

/* ---------- clock ---------- */
function tick(t) {
  if (!root.isConnected) return teardown();
  raf = 0;
  const dt = Math.min(.25, (t - last) / 1000);
  last = t;
  if (!playing) return;
  elapsed += dt;
  if (elapsed >= now.d) {
    if (queue.length) playAt(0, 'Up next');
    else { elapsed = now.d; ended = true; setPlaying(false); say('End of queue'); }
  }
  progress();
  if (playing && visible && !document.hidden) raf = requestAnimationFrame(tick);
}
function kick() { if (!raf && playing && visible && !document.hidden) { last = performance.now(); raf = requestAnimationFrame(tick); } }
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) return teardown();
  visible = es[es.length - 1].isIntersecting;
  kick();
});
io.observe(root);
const onVis = () => { if (!root.isConnected) return teardown(); kick(); };
document.addEventListener('visibilitychange', onVis);
function teardown() {
  cancelAnimationFrame(raf); raf = 0; clearTimeout(toastT);
  io.disconnect();
  document.removeEventListener('visibilitychange', onVis);
}

queue.forEach((t) => list.append(rowFor(t)));
renderNow();
sync();
setPlaying(true);

