/* Re-theme with --mmd-cull-bg, -fg, -pick and -reject. */
.mmd-cull {
  --mmd-cull-bg: oklch(0.225 0.006 260);
  --mmd-cull-fg: oklch(0.94 0.005 260);
  --mmd-cull-pick: oklch(0.86 0.16 92);
  --mmd-cull-reject: oklch(0.65 0.2 25);

  --mmd-cull-dim: color-mix(in oklch, var(--mmd-cull-fg) 55%, var(--mmd-cull-bg));
  --mmd-cull-line: color-mix(in oklch, var(--mmd-cull-fg) 10%, transparent);
  --mmd-cull-raise: color-mix(in oklch, var(--mmd-cull-fg) 7%, var(--mmd-cull-bg));
  --mmd-cull-well: color-mix(in oklch, black 22%, var(--mmd-cull-bg));
  --mmd-cull-ease: cubic-bezier(.22, 1, .36, 1);
  --mmd-cull-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "sheet" "foot";
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr) auto;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  height: 420px;
  border-radius: 16px;
  overflow: hidden;
  overflow: clip;
  background: var(--mmd-cull-bg);
  color: var(--mmd-cull-fg);
  box-shadow: inset 0 0 0 1px var(--mmd-cull-line);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mmd-cull { --mmd-cull-spring: cubic-bezier(.3, 1.4, .5, 1); }
}
:where(.mmd-cull) *, :where(.mmd-cull) *::before, :where(.mmd-cull) *::after { box-sizing: border-box; }
:where(.mmd-cull) :is(p, h3) { margin: 0; }
:where(.mmd-cull) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mmd-cull) :focus-visible { outline: 2px solid var(--mmd-cull-pick); outline-offset: 2px; }
.mmd-cull svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; flex: none; }
.mmd-cull kbd { font: 600 10.5px/1 ui-monospace, Menlo, monospace; padding: 2px 5px; border-radius: 4px; background: var(--mmd-cull-raise); box-shadow: inset 0 -1px 0 var(--mmd-cull-line); }

.mmd-cull__head {
  grid-area: head; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 6px 10px;
  padding: 12px 12px 10px;
  & p { font: 500 10.5px/1.3 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mmd-cull-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & h3 { font-size: clamp(15px, 4.8cqi, 18px); font-weight: 720; letter-spacing: -.015em; line-height: 1.2; }
}
.mmd-cull__filters {
  display: flex; padding: 2px; border-radius: 9px; background: var(--mmd-cull-well); box-shadow: inset 0 0 0 1px var(--mmd-cull-line);
  & button { display: inline-flex; align-items: baseline; gap: 5px; height: 26px; padding: 0 9px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--mmd-cull-dim); line-height: 26px; transition: background-color .2s, color .2s; }
  & b { font: 600 10.5px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; opacity: .8; }
  & button:hover { color: var(--mmd-cull-fg); }
  & button[aria-checked="true"] { background: var(--mmd-cull-raise); color: var(--mmd-cull-fg); box-shadow: 0 1px 2px oklch(0 0 0 / .4), inset 0 0 0 1px var(--mmd-cull-line); }
  & [data-f="pick"] b { color: var(--mmd-cull-pick); }
  & [data-f="reject"] b { color: var(--mmd-cull-reject); }
}
@container (width < 350px) {
  .mmd-cull__head { grid-template-columns: 1fr; }
  .mmd-cull__filters { justify-self: start; }
}

/* ---------- sheet ---------- */
.mmd-cull__sheet {
  grid-area: sheet; position: relative; min-height: 0; overflow-y: auto; overscroll-behavior: contain;
  padding: 10px 12px 12px; background: var(--mmd-cull-well);
  border-block: 1px solid var(--mmd-cull-line);
  scrollbar-width: thin; scrollbar-color: var(--mmd-cull-line) transparent;
}
.mmd-cull__grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px 8px; outline: none; }
@container (width >= 400px) { .mmd-cull__grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.mmd-cull__tile {
  position: relative; display: grid; gap: 4px; outline: none; cursor: pointer;
  & canvas {
    display: block; width: 100%; aspect-ratio: 3 / 2; border-radius: 3px; background: oklch(0.3 0.01 260);
    box-shadow: 0 0 0 1px oklch(0 0 0 / .5), 0 4px 10px -4px oklch(0 0 0 / .6);
    transition: filter .35s, opacity .35s, box-shadow .2s, scale .3s var(--mmd-cull-spring);
  }
  &:hover canvas { scale: 1.03; }
  &[aria-selected="true"] canvas { box-shadow: 0 0 0 2px var(--mmd-cull-fg), 0 6px 14px -4px oklch(0 0 0 / .7); }
  &:focus-visible canvas { box-shadow: 0 0 0 2px var(--mmd-cull-bg), 0 0 0 4px var(--mmd-cull-pick); }
  &[data-flag="reject"] canvas { filter: grayscale(1) brightness(.5); opacity: .7; }
  &[hidden] { display: none; }
}
.mmd-cull__cap {
  display: flex; align-items: center; justify-content: space-between; gap: 4px; min-width: 0;
  font: 500 10px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mmd-cull-dim);
}
.mmd-cull__stars {
  display: inline-flex; gap: 1.5px;
  & i { width: 4px; height: 4px; border-radius: 50%; background: var(--mmd-cull-line); transition: background-color .2s, scale .3s var(--mmd-cull-spring); }
}
.mmd-cull__tile:is([data-stars="1"], [data-stars="2"], [data-stars="3"], [data-stars="4"], [data-stars="5"]) .mmd-cull__stars i:nth-child(1),
.mmd-cull__tile:is([data-stars="2"], [data-stars="3"], [data-stars="4"], [data-stars="5"]) .mmd-cull__stars i:nth-child(2),
.mmd-cull__tile:is([data-stars="3"], [data-stars="4"], [data-stars="5"]) .mmd-cull__stars i:nth-child(3),
.mmd-cull__tile:is([data-stars="4"], [data-stars="5"]) .mmd-cull__stars i:nth-child(4),
.mmd-cull__tile[data-stars="5"] .mmd-cull__stars i:nth-child(5) { background: var(--mmd-cull-fg); }
.mmd-cull__badge {
  position: absolute; top: 4px; right: 4px; width: 18px; height: 18px; border-radius: 5px;
  display: grid; place-items: center; scale: 0; opacity: 0;
  transition: scale .4s var(--mmd-cull-spring), opacity .15s;
  & svg { width: 12px; height: 12px; stroke-width: 2.6; }
  & path { display: none; }
}
.mmd-cull__tile[data-flag="pick"] .mmd-cull__badge { scale: 1; opacity: 1; background: var(--mmd-cull-pick); color: oklch(0.25 0.04 92); & .mmd-cull__gp { display: block; } }
.mmd-cull__tile[data-flag="reject"] .mmd-cull__badge { scale: 1; opacity: 1; background: var(--mmd-cull-reject); color: white; & .mmd-cull__gx { display: block; } }
.mmd-cull__tile[data-flag="pick"] .mmd-cull__cap span:first-child { color: var(--mmd-cull-pick); }

.mmd-cull__empty {
  display: none; position: absolute; inset: 0; place-content: center; justify-items: center; gap: 4px; text-align: center; padding: 20px;
  color: var(--mmd-cull-dim); font-size: 12px;
  & svg { width: 30px; height: 30px; stroke-width: 1.6; margin-bottom: 4px; }
  & b { color: var(--mmd-cull-fg); font-size: 13.5px; font-weight: 650; }
}
.mmd-cull[data-none] .mmd-cull__empty { display: grid; animation: mmd-cull-fade .4s var(--mmd-cull-ease); }
@keyframes mmd-cull-fade { from { opacity: 0; translate: 0 6px; } }

/* ---------- footer ---------- */
.mmd-cull__foot {
  grid-area: foot; display: grid; grid-template-columns: minmax(0, 1fr) auto auto; grid-template-areas: "exif zoom btn" "tally zoom btn"; align-items: center; column-gap: 6px;
  padding: 9px 12px 11px;
}
