.mmd-cull[data-none] .mmd-cull__zoom { opacity: .35; pointer-events: none; }
.mmd-cull__exif { grid-area: exif; font: 500 10.5px/1.4 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mmd-cull-fg); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mmd-cull__tally { grid-area: tally; font-size: 11px; color: var(--mmd-cull-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mmd-cull__export {
  grid-area: btn; position: relative; overflow: hidden; isolation: isolate; height: 32px; padding: 0 13px; border-radius: 9px;
  background: var(--mmd-cull-pick); color: oklch(0.24 0.04 92); font-size: 12px; font-weight: 700; white-space: nowrap;
