  &[data-busy]::before { animation: mmd-cull-fill 1.3s cubic-bezier(.4, .1, .3, 1) forwards; }
  &[data-done] { background: color-mix(in oklch, var(--mmd-cull-pick) 18%, var(--mmd-cull-bg)); color: var(--mmd-cull-pick); }
