}
.mmd-cull[data-loupe] .mmd-cull__loupe { display: grid; }
.mmd-cull__stage {
  position: relative; display: grid; place-items: center; padding: 0 12px; min-height: 0;
  & .mmd-cull__frame { position: relative; width: 100%; }
  & canvas { width: 100%; aspect-ratio: 3 / 2; display: block; border-radius: 4px; box-shadow: 0 16px 40px -14px black; transition: filter .35s; }
}
.mmd-cull__loupe[data-flag="reject"] .mmd-cull__stage canvas { filter: grayscale(1) brightness(.55); }
.mmd-cull__lflag {
  position: absolute; top: 8px; right: 8px; padding: 3px 8px; border-radius: 6px; font-size: 10.5px; font-weight: 750; letter-spacing: .06em; text-transform: uppercase;
  opacity: 0; scale: .7; transition: scale .4s var(--mmd-cull-spring), opacity .15s;
}
.mmd-cull__loupe[data-flag="pick"] .mmd-cull__lflag { opacity: 1; scale: 1; background: var(--mmd-cull-pick); color: oklch(0.24 0.04 92); &::before { content: "Pick"; } }
.mmd-cull__loupe[data-flag="reject"] .mmd-cull__lflag { opacity: 1; scale: 1; background: var(--mmd-cull-reject); color: white; &::before { content: "Reject"; } }
.mmd-cull__nav {
  position: absolute; top: 50%; translate: 0 -50%; z-index: 1;
  background: oklch(0.15 0.01 260 / .7); color: var(--mmd-cull-fg) !important;
  &[data-act="prev"] { left: 8px; }
  &[data-act="next"] { right: 8px; }
