}
.mmd-cull__tools { display: flex; align-items: center; justify-content: center; gap: 6px; padding: 10px 8px 12px; flex-wrap: wrap; }
.mmd-cull__ib {
  width: 30px; height: 30px; display: grid; place-items: center; border-radius: 8px; color: var(--mmd-cull-dim);
  &:hover { background: var(--mmd-cull-raise); color: var(--mmd-cull-fg); }
}
.mmd-cull__fb {
  display: inline-flex; align-items: center; gap: 5px; height: 30px; padding: 0 10px 0 8px; border-radius: 8px;
  font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--mmd-cull-line);
  transition: background-color .2s, color .2s;
  & svg { width: 14px; height: 14px; }
  &:hover { background: var(--mmd-cull-raise); }
  &[data-act="pick"][aria-pressed="true"] { background: var(--mmd-cull-pick); color: oklch(0.24 0.04 92); box-shadow: none; }
  &[data-act="reject"][aria-pressed="true"] { background: var(--mmd-cull-reject); color: white; box-shadow: none; }
}
.mmd-cull__rate {
  display: flex; padding: 0 2px;
  & button { width: 22px; height: 30px; display: grid; place-items: center; color: var(--mmd-cull-line); transition: color .15s, scale .3s var(--mmd-cull-spring); }
  & button svg { width: 15px; height: 15px; fill: currentColor; stroke: none; }
  & button[data-on] { color: var(--mmd-cull-fg); }
  & button:hover { scale: 1.15; }
  &:hover button { color: var(--mmd-cull-dim); }
  &:hover button:hover ~ button { color: var(--mmd-cull-line); }
  &:hover button:has(~ button:hover), &:hover button:hover { color: var(--mmd-cull-pick); }
}
.mmd-cull__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (width < 330px) {
  .mmd-cull__foot { grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "exif exif" "tally tally" "zoom btn"; row-gap: 2px; }
  .mmd-cull__foot button { margin-top: 6px; }
  .mmd-cull__export { justify-self: stretch; }
}

@media (prefers-reduced-motion: reduce) {
  .mmd-cull *, .mmd-cull *::before, .mmd-cull *::after { transition-duration: .01ms !important; }
  .mmd-cull[data-none] .mmd-cull__empty { animation: none; }
  .mmd-cull__tile:hover canvas { scale: 1; }
  .mmd-cull__export[data-busy]::before { animation-duration: .6s; animation-timing-function: steps(3, end); }
}

