const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1)';
const EASE = 'cubic-bezier(.22, 1, .36, 1)';
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

/* ---------- the roll: exposure data agrees with what is painted ---------- */
/* n, time, shutter, aperture, iso, mm, ev, sun [x,y], boats, extra */
const ROLL = [
  [401, '19:41:02', '1/250', 4, 200, 35, 0, [.74, .44], [.22], {}],
  [402, '19:42:15', '1/250', 4, 200, 35, 0, [.71, .48], [.26, .55], {}],
  [403, '19:42:18', '1/500', 4, 200, 35, -1, [.71, .48], [.27, .55], {}],
  [404, '19:44:40', '1/30', 4, 200, 35, 0, [.69, .51], [.3, .57], { blur: 1 }],
  [405, '19:47:09', '1/250', 5.6, 400, 50, .1, [.66, .55], [.42], { zoom: 1.45 }],
  [406, '19:49:31', '1/200', 4, 400, 35, 0, [.63, .57], [.45], { tilt: -4 }],
  [407, '19:52:02', '1/160', 4, 400, 35, .2, [.61, .6], [.48, .72], {}],
  [408, '19:55:47', '1/125', 4, 400, 35, 0, [.59, .63], [.5], { gulls: 3 }],
  [409, '19:58:20', '1/125', 4, 400, 35, .1, [.57, .66], [.53], { gulls: 1 }],
  [410, '20:01:05', '1/200', 4, 400, 35, -.6, [.55, .7], [], {}],
  [411, '20:03:44', '1/40', 4, 400, 35, 1.6, [.54, .72], [.6], {}],
  [412, '20:07:12', '1/60', 4, 800, 35, -.1, [.52, .76], [.62], { lamps: 1 }]
].map(([n, time, ss, f, iso, mm, ev, sun, boats, x]) => ({ n, time, ss, f, iso, mm, ev, sun, boats, ...x, flag: '', stars: 0 }));
const INIT = { 402: ['pick', 4], 404: ['reject', 0], 405: ['pick', 3], 409: ['pick', 5], 411: ['reject', 0] };
ROLL.forEach((F) => { if (INIT[F.n]) [F.flag, F.stars] = INIT[F.n]; });
const name = (F) => 'R07_0' + F.n;
const exif = (F) => F.ss + ' s · ƒ/' + F.f + ' · ISO ' + F.iso + ' · ' + F.mm + ' mm';

const mixc = (a, b, k) => a.map((v, i) => v + (b[i] - v) * k);
const col = (c, a = 1) => 'rgb(' + (c[0] | 0) + ' ' + (c[1] | 0) + ' ' + (c[2] | 0) + ' / ' + a + ')';
const rnd = (n) => { const x = Math.sin(n * 12.9898 + 78.233) * 43758.5453; return x - Math.floor(x); };

function scene(g, w, h, F) {
  const p = (F.n - 401) / 11, hz = h * .62, u = h / 100;
  g.save();
  if (F.tilt) { g.translate(w / 2, h / 2); g.rotate(F.tilt * Math.PI / 180); g.scale(1.1, 1.1); g.translate(-w / 2, -h / 2); }
  if (F.zoom) { const sx = w * F.sun[0], sy = h * F.sun[1]; g.translate(w / 2, h / 2); g.scale(F.zoom, F.zoom); g.translate(-sx + (sx - w / 2) * .35, -sy + (sy - h / 2) * .2); }
  let gr = g.createLinearGradient(0, 0, 0, hz);
  gr.addColorStop(0, col(mixc([62, 86, 146], [24, 28, 70], p)));
  gr.addColorStop(.62, col(mixc([214, 140, 120], [170, 80, 96], p)));
  gr.addColorStop(1, col(mixc([255, 204, 136], [248, 140, 82], p)));
  g.fillStyle = gr; g.fillRect(-w, -h, w * 3, hz + h);
  const sx = w * F.sun[0], sy = h * F.sun[1], r = u * 6.5;
  const glow = g.createRadialGradient(sx, sy, 0, sx, sy, r * 7);
  glow.addColorStop(0, 'rgb(255 222 170 / .65)'); glow.addColorStop(1, 'rgb(255 222 170 / 0)');
  g.fillStyle = glow; g.fillRect(-w, -h, w * 3, hz + h);
  g.fillStyle = col(mixc([255, 244, 214], [255, 196, 130], p));
  g.beginPath(); g.arc(sx, sy, r, 0, Math.PI * 2); g.fill();
  for (let i = 0; i < 4; i++) {
    g.fillStyle = col(mixc([150, 90, 110], [90, 50, 80], p), .5);
