@property --mmd-diff-x {
  syntax: "<number>";
  inherits: true;
  initial-value: .5;
}

/* Re-theme with --mmd-diff-bg, -fg and -accent. */
.mmd-diff {
  --mmd-diff-bg: oklch(0.205 0.012 255);
  --mmd-diff-fg: oklch(0.95 0.006 255);
  --mmd-diff-accent: oklch(0.86 0.17 128);

  --mmd-diff-dim: color-mix(in oklch, var(--mmd-diff-fg) 56%, var(--mmd-diff-bg));
  --mmd-diff-line: color-mix(in oklch, var(--mmd-diff-fg) 11%, transparent);
  --mmd-diff-raise: color-mix(in oklch, var(--mmd-diff-fg) 7%, var(--mmd-diff-bg));
  --mmd-diff-well: color-mix(in oklch, black 25%, var(--mmd-diff-bg));
  --mmd-diff-on: oklch(0.22 0.05 128);
  --mmd-diff-ease: cubic-bezier(.22, 1, .36, 1);
  --mmd-diff-spring: linear(0, 0.034 2.3%, 0.13 4.7%, 0.484 11.6%, 0.656 15.5%, 0.786 19.5%, 0.883 23.6%, 0.951 27.9%, 1.006 33.3%, 1.03 38.5%, 1.037 44.2%, 1.025 54.1%, 1.008 66.8%, 1);
  --mmd-diff-o: .5;

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "stack" "bar" "changes" "foot";
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 12px;
  border-radius: 18px;
  background: var(--mmd-diff-bg);
  color: var(--mmd-diff-fg);
  box-shadow: inset 0 0 0 1px var(--mmd-diff-line);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mmd-diff { --mmd-diff-spring: cubic-bezier(.3, 1.4, .5, 1); }
}
:where(.mmd-diff) *, :where(.mmd-diff) *::before, :where(.mmd-diff) *::after { box-sizing: border-box; }
:where(.mmd-diff) :is(p, h3, ol) { margin: 0; padding: 0; }
:where(.mmd-diff) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.mmd-diff) :focus-visible { outline: 2px solid var(--mmd-diff-accent); outline-offset: 2px; }
.mmd-diff svg { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.mmd-diff__head {
  grid-area: head; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 8px; margin-bottom: 10px;
  & div { min-width: 0; }
  & div > p { font-size: 10px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--mmd-diff-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & h3 { display: flex; align-items: center; gap: 6px; font-size: clamp(15px, 4.8cqi, 17px); font-weight: 700; letter-spacing: -.01em; }
  & h3 svg { width: 14px; height: 14px; color: var(--mmd-diff-dim); }
}
.mmd-diff__v {
  padding: 1px 7px; border-radius: 6px; font: 650 12px/1.5 ui-monospace, Menlo, monospace;
  background: var(--mmd-diff-raise); box-shadow: inset 0 0 0 1px var(--mmd-diff-line);
}
.mmd-diff__v--b { background: color-mix(in oklch, var(--mmd-diff-accent) 18%, var(--mmd-diff-bg)); color: var(--mmd-diff-accent); box-shadow: none; }
.mmd-diff__state {
  font: 600 11px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mmd-diff-dim); white-space: nowrap;
  padding: 5px 8px; border-radius: 999px; box-shadow: inset 0 0 0 1px var(--mmd-diff-line);
}
.mmd-diff[data-approved] .mmd-diff__state { color: var(--mmd-diff-on); background: var(--mmd-diff-accent); box-shadow: none; animation: mmd-diff-pop .5s var(--mmd-diff-spring); }
@keyframes mmd-diff-pop { from { scale: .7; } }

/* ---------- the stack ---------- */
.mmd-diff__stack {
  grid-area: stack; position: relative; container-type: inline-size;
  aspect-ratio: 5 / 4; border-radius: 12px; overflow: hidden; outline: none;
  background: var(--mmd-diff-well); touch-action: pan-y; cursor: ew-resize;
  box-shadow: inset 0 0 0 1px var(--mmd-diff-line);
  &:focus-visible { box-shadow: 0 0 0 2px var(--mmd-diff-bg), 0 0 0 4px var(--mmd-diff-accent); }
}
.mmd-diff:not([data-mode="swipe"]) .mmd-diff__stack { cursor: default; }
.mmd-diff__layers { position: absolute; inset: 0; isolation: isolate; background: black; }
.mmd-diff__mock {
  position: absolute; inset: 0;
  display: grid; grid-template-rows: 54% 1fr;
  background: oklch(0.985 0.004 95); color: oklch(0.24 0.02 150);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}
.mmd-diff__img {
  position: relative; margin: 4cqi 4cqi 0; border-radius: 2.6cqi; overflow: hidden;
  background: linear-gradient(oklch(0.92 0.03 210), oklch(0.95 0.02 120));
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; }
  & .mmd-diff__hill { fill: oklch(0.78 0.08 140); stroke: none; }
  & .mmd-diff__fly { fill: oklch(0.62 0.13 45); stroke: oklch(0.4 0.09 40); stroke-width: 1; }
  & .mmd-diff__door { fill: oklch(0.36 0.07 40); stroke: none; }
  & .mmd-diff__pole { stroke: oklch(0.35 0.03 60); stroke-width: 1.2; }
}
.mmd-diff__badge {
  position: absolute; left: 3cqi; top: 3cqi; z-index: 1; padding: .8cqi 2.4cqi; border-radius: 99px;
  background: oklch(0.3 0.05 150); color: white; font-size: 3.4cqi; font-weight: 700; letter-spacing: .04em;
}
.mmd-diff__body { display: grid; align-content: start; gap: .6cqi; padding: 3.2cqi 4.5cqi 0; }
.mmd-diff__brand { font-size: 3.2cqi; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: oklch(0.55 0.05 150); }
.mmd-diff__title { font-size: 5.6cqi; font-weight: 750; letter-spacing: -.02em; line-height: 1.1; }
.mmd-diff__meta { font-size: 3.4cqi; color: oklch(0.5 0.02 150); }
.mmd-diff__stars { color: oklch(0.72 0.15 75); letter-spacing: .1em; margin-right: 1.2cqi; }
.mmd-diff__buy {
  display: flex; align-items: center; justify-content: space-between; margin-top: 2.2cqi;
  & p { display: flex; align-items: baseline; gap: 1.6cqi; }
  & b { font-size: 6cqi; font-weight: 800; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & s { font-size: 3.6cqi; color: oklch(0.55 0.02 150); }
}
.mmd-diff__btn { padding: 2cqi 4.4cqi; border-radius: 2cqi; background: oklch(0.32 0.06 150); color: white; font-size: 3.6cqi; font-weight: 650; white-space: nowrap; }

/* the four ways the top layer composites */
.mmd-diff__mock[data-v="b"] {
  clip-path: inset(0 0 0 calc(var(--mmd-diff-x) * 100%));
  transition: clip-path .5s var(--mmd-diff-ease), opacity .3s linear;
}
.mmd-diff[data-mode="onion"] .mmd-diff__mock[data-v="b"] { clip-path: inset(0 0 0 0); opacity: var(--mmd-diff-o); }
.mmd-diff[data-mode="diff"] .mmd-diff__mock[data-v="b"] { clip-path: inset(0 0 0 0); mix-blend-mode: difference; }
.mmd-diff[data-mode="blink"] .mmd-diff__mock[data-v="b"] { clip-path: inset(0 0 0 0); animation: mmd-diff-blink 1.1s steps(1, end) infinite; }
.mmd-diff[data-drag] .mmd-diff__mock[data-v="b"] { transition: none; }
@keyframes mmd-diff-blink { 0% { opacity: 0; } 50% { opacity: 1; } }

.mmd-diff__split {
  position: absolute; top: 0; bottom: 0; left: -1px; width: 2px; z-index: 3; pointer-events: none;
  background: var(--mmd-diff-accent); box-shadow: 0 0 0 1px oklch(0 0 0 / .25);
  translate: calc(var(--mmd-diff-x) * 100cqi) 0;
  transition: translate .5s var(--mmd-diff-ease), opacity .25s linear;
  & b {
    position: absolute; left: 50%; top: 50%; width: 28px; height: 28px; margin: -14px 0 0 -14px; border-radius: 50%;
    background: var(--mmd-diff-accent); box-shadow: 0 4px 12px -2px oklch(0 0 0 / .5);
    transition: scale .3s var(--mmd-diff-spring);
  }
  & b::before, & b::after { content: ""; position: absolute; top: 50%; width: 0; height: 0; margin-top: -4px; border: 4px solid transparent; }
  & b::before { left: 5px; border-right-color: var(--mmd-diff-on); }
  & b::after { right: 5px; border-left-color: var(--mmd-diff-on); }
}
.mmd-diff[data-drag] .mmd-diff__split { transition: none; & b { scale: 1.15; } }
.mmd-diff:not([data-mode="swipe"]) .mmd-diff__split { opacity: 0; }
.mmd-diff__tag {
  position: absolute; top: 8px; z-index: 2; padding: 2px 7px; border-radius: 6px; pointer-events: none;
  font: 650 10.5px/1.4 ui-monospace, Menlo, monospace; background: oklch(0.15 0.01 255 / .78); color: white;
  transition: opacity .25s linear;
  &[data-t="a"] { left: 8px; }
  &[data-t="b"] { right: 8px; background: var(--mmd-diff-accent); color: var(--mmd-diff-on); }
}
.mmd-diff:is([data-mode="onion"], [data-mode="diff"]) .mmd-diff__tag { opacity: 0; }
.mmd-diff[data-mode="blink"] .mmd-diff__tag {
  &[data-t="a"] { left: 50%; translate: -50% 0; animation: mmd-diff-blink 1.1s steps(1, end) infinite reverse; }
  &[data-t="b"] { right: auto; left: 50%; translate: -50% 0; animation: mmd-diff-blink 1.1s steps(1, end) infinite; }
}
.mmd-diff__regions i {
  position: absolute; z-index: 2; border-radius: 6px; pointer-events: none;
  left: calc(var(--x) * 1%); top: calc(var(--y) * 1%); width: calc(var(--w) * 1%); height: calc(var(--h) * 1%);
  outline: 1.5px dashed transparent; outline-offset: 2px;
  transition: outline-color .2s, background-color .2s;
  &::before {
    content: attr(data-n); position: absolute; right: -8px; top: -8px; width: 18px; height: 18px; border-radius: 50%;
    display: grid; place-items: center; font: 750 10px/1 ui-monospace, Menlo, monospace;
    background: var(--mmd-diff-accent); color: var(--mmd-diff-on);
    box-shadow: 0 2px 6px oklch(0 0 0 / .4);
    scale: 0; transition: scale .35s var(--mmd-diff-spring);
  }
  &[data-seen]::before { background: var(--mmd-diff-fg); }
}
.mmd-diff[data-mode="diff"] .mmd-diff__regions i::before, .mmd-diff__regions i[data-hot]::before { scale: 1; }
.mmd-diff__regions i[data-hot] { outline-color: var(--mmd-diff-accent); background: color-mix(in oklch, var(--mmd-diff-accent) 10%, transparent); }

/* ---------- controls ---------- */
.mmd-diff__bar { grid-area: bar; display: flex; align-items: center; gap: 10px; margin-top: 10px; min-width: 0; }
.mmd-diff__modes {
  display: flex; padding: 2px; border-radius: 10px; background: var(--mmd-diff-well); box-shadow: inset 0 0 0 1px var(--mmd-diff-line);
  & button { height: 28px; padding: 0 10px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--mmd-diff-dim); transition: color .2s, background-color .2s; }
  & button:hover { color: var(--mmd-diff-fg); }
  & button[aria-checked="true"] { background: var(--mmd-diff-raise); color: var(--mmd-diff-fg); box-shadow: 0 1px 2px oklch(0 0 0 / .4), inset 0 0 0 1px var(--mmd-diff-line); }
}
.mmd-diff__onion { flex: 1; min-width: 50px; margin: 0; accent-color: var(--mmd-diff-accent); visibility: hidden; }
.mmd-diff[data-mode="onion"] .mmd-diff__onion { visibility: visible; }
.mmd-diff__changes {
  grid-area: changes; list-style: none; display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px;
  & button {
    display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px 0 4px; border-radius: 999px;
    font-size: 12px; font-weight: 600; color: var(--mmd-diff-dim); box-shadow: inset 0 0 0 1px var(--mmd-diff-line);
    transition: color .15s, background-color .15s, box-shadow .15s;
  }
  & button > i {
    width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; font: 750 10.5px/1 ui-monospace, Menlo, monospace; font-style: normal;
    background: var(--mmd-diff-raise); color: var(--mmd-diff-fg); transition: background-color .2s, color .2s;
  }
  & button:hover { color: var(--mmd-diff-fg); background: var(--mmd-diff-raise); }
  & button[aria-pressed="true"] { color: var(--mmd-diff-fg); box-shadow: inset 0 0 0 1.5px var(--mmd-diff-accent); }
  & li[data-seen] button > i { background: var(--mmd-diff-accent); color: var(--mmd-diff-on); }
  & li { animation: mmd-diff-in .4s var(--mmd-diff-ease) both; animation-delay: calc(var(--i) * 50ms); }
}
@keyframes mmd-diff-in { from { opacity: 0; transform: translateY(4px); } }
.mmd-diff__foot {
  grid-area: foot; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 10px;
  margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--mmd-diff-line);
}
.mmd-diff__detail {
  font-size: 12px; line-height: 1.35; color: var(--mmd-diff-dim); text-wrap: pretty; min-width: 0;
  & b { color: var(--mmd-diff-fg); font-weight: 650; }
  & code { font: 600 11.5px/1 ui-monospace, Menlo, monospace; color: var(--mmd-diff-fg); }
}
.mmd-diff__approve {
  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px; border-radius: 9px;
  background: var(--mmd-diff-accent); color: var(--mmd-diff-on); font-size: 12px; font-weight: 700; white-space: nowrap;
  transition: opacity .2s, scale .25s var(--mmd-diff-spring), background-color .2s, color .2s;
  & svg { width: 15px; height: 15px; stroke-width: 2.6; display: none; }
  &:active:not(:disabled) { scale: .96; }
  &:disabled { opacity: .35; cursor: not-allowed; }
}
.mmd-diff[data-approved] .mmd-diff__approve { background: var(--mmd-diff-raise); color: var(--mmd-diff-fg); box-shadow: inset 0 0 0 1px var(--mmd-diff-line); & svg { display: block; color: var(--mmd-diff-accent); } }
.mmd-diff__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (width < 340px) {
  .mmd-diff__modes button { padding: 0 8px; font-size: 11.5px; }
  .mmd-diff__bar { gap: 6px; }
}

@media (prefers-reduced-motion: reduce) {
  .mmd-diff *, .mmd-diff *::before, .mmd-diff *::after { transition-duration: .01ms !important; }
  .mmd-diff__changes li, .mmd-diff[data-approved] .mmd-diff__state { animation: none; }
  .mmd-diff[data-mode="blink"] .mmd-diff__mock[data-v="b"], .mmd-diff[data-mode="blink"] .mmd-diff__tag { animation-duration: 2.4s; }
}

