const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);

/* each change names the elements it touches in v12 (a) and v13 (b); its region is measured from them */
const CHANGES = [
  { n: 1, label: 'Badge', detail: '<b>Badge added.</b> <code>New</code> pill on the image, top left.', a: [], b: ['.mmd-diff__badge'] },
  { n: 2, label: 'Image', detail: '<b>Image shifted.</b> The tent sits <code>5 units</code> further right in the artwork.', a: ['.mmd-diff__fly', '.mmd-diff__pole'], b: ['.mmd-diff__img g'] },
  { n: 3, label: 'Price', detail: '<b>Price.</b> <code>€129</code> → <code>€119</code>, old price struck through.', a: ['.mmd-diff__buy p'], b: ['.mmd-diff__buy p'] },
  { n: 4, label: 'Button', detail: '<b>Button label.</b> <code>Add to bag</code> → <code>Add to cart</code>.', a: ['.mmd-diff__btn'], b: ['.mmd-diff__btn'] }
];

const stack = $('.mmd-diff__stack'), onion = $('.mmd-diff__onion'), live = $('.mmd-diff__sr');
const list = $('.mmd-diff__changes'), regions = $('.mmd-diff__regions'), approve = $('[data-act="approve"]');
const say = (m) => { live.textContent = ''; later(30, () => { live.textContent = m; }); };
list.innerHTML = CHANGES.map((c, i) => '<li style="--i:' + i + '"><button type="button" aria-pressed="false" data-c="' + i + '"><i>' + c.n + '</i>' + c.label + '</button></li>').join('');
regions.innerHTML = CHANGES.map((c) => '<i data-n="' + c.n + '"></i>').join('');
const chips = $$('button', list), boxes = $$('i', regions);

let mode = 'swipe', x = .5, hot = -1, approved = false, drag = false;
const seen = new Set();

function setX(v, animate) {
  x = clamp(v, 0, 1);
  if (!animate) root.setAttribute('data-drag', '');
  root.style.setProperty('--mmd-diff-x', x.toFixed(4));
  if (!animate) requestAnimationFrame(() => { if (!root.isConnected) return; if (!drag) root.removeAttribute('data-drag'); });
  const p = Math.round(x * 100);
  stack.setAttribute('aria-valuenow', p);
  stack.setAttribute('aria-valuetext', p + '% v12, ' + (100 - p) + '% v13');
}
function setMode(m, focus) {
  mode = m;
  root.dataset.mode = m;
  $$('.mmd-diff__modes [role="radio"]').forEach((b) => { const on = b.dataset.mode === m; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
  if (m === 'swipe') { stack.setAttribute('role', 'slider'); stack.setAttribute('aria-label', 'Swipe between v12 and v13'); stack.tabIndex = 0; }
  else { stack.removeAttribute('role'); ['aria-valuenow', 'aria-valuetext', 'aria-valuemin', 'aria-valuemax'].forEach((a) => stack.removeAttribute(a)); stack.tabIndex = -1; stack.setAttribute('aria-label', 'Comparison'); }
  if (m === 'swipe') { stack.setAttribute('aria-valuemin', '0'); stack.setAttribute('aria-valuemax', '100'); setX(x, true); }
  say({ swipe: 'Swipe. Drag or use arrow keys.', onion: 'Onion skin. Adjust v13 opacity.', diff: 'Difference. Unchanged pixels turn black.', blink: 'Blink. Alternating v12 and v13.' }[m]);
  sync();
}
function sync() {
  const left = CHANGES.length - seen.size;
  approve.disabled = approved || left > 0;
  $('span', approve).textContent = approved ? 'Approved' : 'Approve v13';
  $('[data-state-label]').textContent = approved ? 'Approved' : left ? seen.size + '/' + CHANGES.length + ' reviewed' : 'Ready to approve';
  if (!approved && left) approve.setAttribute('aria-description', left + ' changes still to review'); else approve.removeAttribute('aria-description');
  CHANGES.forEach((c, i) => {
    chips[i].closest('li').toggleAttribute('data-seen', seen.has(i));
    chips[i].setAttribute('aria-pressed', String(i === hot));
    chips[i].setAttribute('aria-label', c.label + (seen.has(i) ? ', reviewed' : ''));
    boxes[i].toggleAttribute('data-hot', i === hot);
    boxes[i].toggleAttribute('data-seen', seen.has(i));
  });
}
function inspect(i) {
  hot = hot === i ? -1 : i;
  const det = $('[data-detail]');
  if (hot < 0) { det.textContent = 'Select a change to inspect it.'; sync(); return; }
  const c = CHANGES[i];
  seen.add(i);
  det.innerHTML = c.detail;
  if (!RM.matches) det.animate([{ opacity: 0, transform: 'translateY(3px)' }, { opacity: 1, transform: 'none' }], { duration: 260, easing: 'cubic-bezier(.22,1,.36,1)' });
  if (mode === 'swipe') setX(c.at || .5, true);
  if (mode === 'onion') { onion.value = 50; root.style.setProperty('--mmd-diff-o', .5); }
  sync();
  say(det.textContent + (seen.size === CHANGES.length && !approved ? ' All changes reviewed.' : ''));
}

/* ---------- swipe input ---------- */
const xAt = (cx) => { const r = stack.getBoundingClientRect(); return (cx - r.left) / r.width; };
stack.addEventListener('pointerdown', (e) => {
  if (mode !== 'swipe' || e.button) return;
  drag = true;
  root.setAttribute('data-drag', '');
  stack.setPointerCapture(e.pointerId);
  setX(xAt(e.clientX));
});
stack.addEventListener('pointermove', (e) => { if (drag) setX(xAt(e.clientX)); });
const end = () => { if (!drag) return; drag = false; root.removeAttribute('data-drag'); };
stack.addEventListener('pointerup', end);
stack.addEventListener('pointercancel', end);
stack.addEventListener('keydown', (e) => {
  if (mode !== 'swipe') return;
  const step = e.shiftKey ? .1 : .02;
  if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') setX(x - step);
  else if (e.key === 'ArrowRight' || e.key === 'ArrowUp') setX(x + step);
  else if (e.key === 'Home') setX(0, true);
  else if (e.key === 'End') setX(1, true);
  else return;
  e.preventDefault();
});
onion.addEventListener('input', () => { root.style.setProperty('--mmd-diff-o', onion.value / 100); });

/* ---------- modes + changes ---------- */
root.addEventListener('click', (e) => {
  const m = e.target.closest('[data-mode][role="radio"]');
  if (m) { setMode(m.dataset.mode); return; }
  const c = e.target.closest('[data-c]');
  if (c) { inspect(+c.dataset.c); return; }
  if (e.target.closest('[data-act="approve"]') && !approve.disabled) {
    approved = true;
    root.setAttribute('data-approved', '');
    sync();
    say('v13 approved');
  }
});
$('.mmd-diff__modes').addEventListener('keydown', (e) => {
  const order = ['swipe', 'onion', 'diff', 'blink'], d = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key];
  if (!d) return;
  e.preventDefault();
  setMode(order[(order.indexOf(mode) + d + 4) % 4], true);
});
list.addEventListener('keydown', (e) => {
  const d = { ArrowRight: 1, ArrowLeft: -1 }[e.key];
  if (!d) return;
  const i = chips.indexOf(document.activeElement);
  if (i < 0) return;
  e.preventDefault();
  chips[(i + d + chips.length) % chips.length].focus();
});
root.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && hot >= 0) { e.preventDefault(); inspect(hot); }
});

/* regions follow the real layout at any width */
function measure() {
  const S = stack.getBoundingClientRect();
  if (!S.width) return;
  const A = $('.mmd-diff__mock[data-v="a"]'), B = $('.mmd-diff__mock[data-v="b"]'), pad = 3;
  CHANGES.forEach((c, i) => {
    let l = Infinity, t = Infinity, r = -Infinity, b = -Infinity;
    [...c.a.map((q) => $(q, A)), ...c.b.map((q) => $(q, B))].forEach((el) => {
      const q = el.getBoundingClientRect();
      l = Math.min(l, q.left); t = Math.min(t, q.top); r = Math.max(r, q.right); b = Math.max(b, q.bottom);
    });
    const box = boxes[i].style;
    box.setProperty('--x', ((l - S.left - pad) / S.width * 100).toFixed(2));
    box.setProperty('--y', ((t - S.top - pad) / S.height * 100).toFixed(2));
    box.setProperty('--w', ((r - l + pad * 2) / S.width * 100).toFixed(2));
    box.setProperty('--h', ((b - t + pad * 2) / S.height * 100).toFixed(2));
    c.at = clamp(((l + r) / 2 - S.left) / S.width, .08, .92);
  });
}
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } measure(); });
ro.observe(stack);

measure();
setX(.5, true);
sync();

css:
@property --mmd-jog-turn {
  syntax: "<angle>";
  inherits: true;
  initial-value: 0deg;
}
@property --mmd-jog-ring {
  syntax: "<angle>";
  inherits: true;
  initial-value: 0deg;
}

/* Re-theme with --mmd-jog-metal, -ink and -accent. */
.mmd-jog {
  --mmd-jog-metal: oklch(0.935 0.005 80);
  --mmd-jog-ink: oklch(0.24 0.012 250);
  --mmd-jog-accent: oklch(0.67 0.19 42);

  --mmd-jog-dim: color-mix(in oklch, var(--mmd-jog-ink) 55%, var(--mmd-jog-metal));
  --mmd-jog-line: color-mix(in oklch, var(--mmd-jog-ink) 13%, transparent);
